/*!40000 ALTER TABLE `papers` DISABLE KEYS */;
INSERT INTO `papers` VALUES
(1,4,'Attention Is All You Need','Các mô hình chuỗi thống trị các phương pháp tiên tiến nhất trong mô hình hóa ngôn ngữ và các bài toán chuyển đổi từ chuỗi sang chuỗi. Trong nghiên cứu này, chúng tôi đề xuất kiến trúc Transformer — một kiến trúc mạng thuần túy dựa trên cơ chế chú ý, hoàn toàn không sử dụng tính toán tuần tự hay tích chập. Các thử nghiệm trên hai bài toán dịch máy cho thấy những mô hình này có chất lượng vượt trội, song song hóa tốt hơn và cần ít thời gian huấn luyện hơn đáng kể. Mô hình của chúng tôi đạt 28,4 BLEU trên bài toán dịch tiếng Anh sang tiếng Đức WMT 2014, cải thiện hơn 2 BLEU so với các kết quả tốt nhất hiện có.','/uploads/attention_is_all_you_need.pdf','2026-04-10 08:15:00',11,'completed',38,NULL,'2026-04-10 08:15:38'),
(2,4,'BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding','Chúng tôi giới thiệu một mô hình mới gọi là BERT (Bidirectional Encoder Representations from Transformers). BERT được thiết kế để tiền huấn luyện các biểu diễn sâu hai chiều từ văn bản không có nhãn, bằng cách điều kiện hóa đồng thời trên cả ngữ cảnh trái và phải ở mọi lớp. Kết quả là mô hình BERT đã được tiền huấn luyện có thể được tinh chỉnh chỉ với một lớp đầu ra bổ sung để tạo ra các mô hình tiên tiến nhất cho nhiều tác vụ NLP, bao gồm hỏi đáp và suy luận ngôn ngữ, mà không cần thay đổi đáng kể kiến trúc đặc thù cho từng tác vụ.','/uploads/bert_paper.pdf','2026-04-11 09:30:00',16,'completed',55,NULL,'2026-04-11 09:30:55'),
(3,4,'Deep Residual Learning for Image Recognition','Chúng tôi trình bày một framework học tàn dư (residual learning) để làm dễ dàng hơn việc huấn luyện các mạng nơ-ron rất sâu. Chúng tôi tái công thức hóa các lớp một cách rõ ràng để học các hàm tàn dư liên quan đến đầu vào của lớp, thay vì học các hàm không có tham chiếu. Chúng tôi cung cấp bằng chứng toàn diện cho thấy những mạng tàn dư này dễ tối ưu hơn và có thể đạt được độ chính xác cao hơn từ độ sâu tăng đáng kể. Trên tập dữ liệu ImageNet, chúng tôi đánh giá các mạng tàn dư với độ sâu lên đến 152 lớp.','/uploads/deep_residual_learning.pdf','2026-04-12 14:00:00',12,'completed',47,NULL,'2026-04-12 14:00:47'),
(4,4,'Generative Adversarial Networks','Chúng tôi đề xuất một framework mới để ước tính các mô hình sinh thông qua một quá trình đối kháng, trong đó chúng tôi đồng thời huấn luyện hai mô hình: một mô hình sinh G nắm bắt phân phối dữ liệu, và một mô hình phân biệt D ước tính xác suất rằng một mẫu đến từ dữ liệu huấn luyện thay vì G. Quy trình huấn luyện cho G là tối đa hóa xác suất D mắc lỗi. Framework này tương ứng với một trò chơi minimax hai người.','/uploads/gan_paper.pdf','2026-04-13 10:00:00',9,'completed',29,NULL,'2026-04-13 10:00:29'),
(5,4,'GPT-4 Technical Report','Chúng tôi báo cáo về GPT-4, một mô hình đa phương thức quy mô lớn có thể chấp nhận đầu vào hình ảnh và văn bản, đồng thời tạo ra đầu ra văn bản. Mặc dù kém hơn con người trong nhiều tình huống thực tế, GPT-4 thể hiện hiệu suất ở mức con người trên nhiều bài kiểm tra học thuật và chuyên nghiệp. Ví dụ, mô hình vượt qua kỳ thi luật sư mô phỏng ở khoảng top 10% số người thi, trái ngược với GPT-3.5, vốn đạt điểm quanh mức bottom 10%.','/uploads/gpt4_technical_report.pdf','2026-04-14 11:30:00',84,'completed',180,NULL,'2026-04-14 11:33:00'),
(6,5,'A Survey on Large Language Models','Kể từ sự ra đời của ChatGPT, các mô hình ngôn ngữ lớn (LLMs) đã thu hút sự chú ý đáng kể từ cả giới học thuật lẫn ngành công nghiệp. Sức mạnh đặc biệt của các LLMs nằm ở khả năng hiểu và tạo ngôn ngữ tự nhiên giống con người. Bài khảo sát này cung cấp tổng quan toàn diện về nền tảng của LLMs, bao gồm lịch sử phát triển, kỹ thuật tiền huấn luyện, các phương pháp thích nghi và sử dụng, cũng như các ứng dụng tiêu biểu.','/uploads/survey_llm.pdf','2026-04-15 09:00:00',31,'completed',75,NULL,'2026-04-15 09:01:15'),
(7,5,'Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks','Chúng tôi khám phá một phương pháp kết hợp bộ nhớ tham số và phi tham số để tạo ngôn ngữ — các nhiệm vụ đòi hỏi nhiều kiến thức tức là sử dụng các mô hình seq2seq kết hợp với truy xuất thưa từ một tài liệu Wikipedia dày đặc. Mô hình của chúng tôi, Retrieval-Augmented Generation (RAG), đạt được kết quả tiên tiến nhất trên ba bài kiểm tra hỏi đáp miền mở.','/uploads/rag_paper.pdf','2026-04-16 10:00:00',14,'completed',42,NULL,'2026-04-16 10:00:42'),
(8,5,'Constitutional AI: Harmlessness from AI Feedback','Chúng tôi giới thiệu một phương pháp để huấn luyện các hệ thống AI vô hại sử dụng chính AI làm phản hồi. Phương pháp bao gồm hai giai đoạn: một giai đoạn học có giám sát, trong đó một mô hình tạo ra và sau đó tự phê bình và sửa đổi các phản hồi của nó dựa trên một tập hợp các nguyên tắc; và một giai đoạn học tăng cường từ phản hồi của AI (RLAIF).','/uploads/constitutional_ai.pdf','2026-04-17 13:00:00',17,'completed',53,NULL,'2026-04-17 13:00:53'),
(9,5,'LLaMA: Open and Efficient Foundation Language Models','Chúng tôi giới thiệu LLaMA, một bộ các mô hình ngôn ngữ nền tảng từ 7B đến 65B tham số. Chúng tôi huấn luyện các mô hình của mình trên hàng nghìn tỷ token và cho thấy rằng có thể huấn luyện các mô hình tiên tiến chỉ sử dụng các bộ dữ liệu có sẵn công khai, mà không cần sử dụng các bộ dữ liệu độc quyền và không thể tiếp cận. Mô hình LLaMA-13B vượt qua GPT-3 (175B) trên hầu hết các bài kiểm tra.','/uploads/llama_paper.pdf','2026-04-18 08:30:00',21,'completed',66,NULL,'2026-04-18 08:31:06'),
(10,5,'Scaling Laws for Neural Language Models','Chúng tôi nghiên cứu các quy luật thực nghiệm cho hiệu suất mô hình ngôn ngữ theo quy mô. Hiệu suất mô hình cải thiện khá trơn tru như một hàm bậc lũy thừa của quy mô mô hình, kích thước tập dữ liệu và lượng tính toán được sử dụng cho quá trình huấn luyện. Một số xu hướng khác tác động ít nhất: kiến trúc mô hình, chiều rộng so với độ sâu trong giới hạn hợp lý và kích hoạt cụ thể.','/uploads/scaling_laws.pdf','2026-04-19 11:00:00',67,'completed',155,NULL,'2026-04-19 11:02:35'),
(11,6,'AlphaFold: Improved protein structure prediction using potentials from deep learning','Chúng tôi mô tả một phương pháp mới sử dụng thông tin tiến hóa, vật lý và hình học của cấu trúc protein để tạo ra một tiềm năng chính xác hơn nhằm dự đoán cấu trúc protein. Tiềm năng này được sử dụng trong quá trình tìm kiếm cấu trúc được hướng dẫn bởi gradient. Chúng tôi cũng mô tả các cải tiến trong kiến trúc mạng nơ-ron, cụ thể là với kiến trúc attention có cấu trúc.','/uploads/alphafold.pdf','2026-04-20 09:00:00',10,'completed',35,NULL,'2026-04-20 09:00:35'),
(12,6,'CRISPR-Cas9 for medical genetic screens in human cells','Kỹ thuật chỉnh sửa gen CRISPR-Cas9 có tiềm năng to lớn trong y học. Bài báo này trình bày kết quả của các màn hình di truyền y tế quy mô lớn trong tế bào người sử dụng CRISPR-Cas9 để xác định các gen liên quan đến kháng thuốc và nhạy cảm với thuốc trong ung thư. Phương pháp của chúng tôi cho phép xác định hàng trăm gen ứng viên, cung cấp cơ sở cho các mục tiêu điều trị mới.','/uploads/crispr_medical.pdf','2026-04-21 10:00:00',8,'completed',24,NULL,'2026-04-21 10:00:24'),
(13,6,'Moderna mRNA-1273 COVID-19 Vaccine Efficacy Trial Results','Chúng tôi báo cáo kết quả thử nghiệm hiệu quả của vaccine COVID-19 dựa trên mRNA mã hóa glycoprotein gai SARS-CoV-2 được ổn định trước khi tiêm chủng. Thử nghiệm ngẫu nhiên, đối chứng giả dược, gồm 30.420 người lớn đăng ký. Vaccine mRNA-1273 có hiệu quả 94,1% trong việc ngăn ngừa COVID-19 có triệu chứng, bao gồm COVID-19 nặng.','/uploads/mrna1273_trial.pdf','2026-04-22 14:00:00',13,'completed',45,NULL,'2026-04-22 14:00:45'),
(14,6,'The Human Microbiome Project: A community resource for the healthy human microbiome','Dự án Microbiome Con người (HMP) đã lấy mẫu từ 242 tình nguyện viên người lớn khỏe mạnh tại 15–18 vị trí cơ thể lên đến ba lần, phân tích mẫu bằng cách giải trình tự 16S rRNA và toàn bộ shotgun metagenome. Kết quả cho thấy sự đa dạng đáng kể giữa các cá nhân và vị trí cơ thể, đồng thời xác định danh mục gen microbiome cốt lõi.','/uploads/human_microbiome.pdf','2026-04-23 09:00:00',18,'completed',54,NULL,'2026-04-23 09:00:54'),
(15,6,'Molecular mechanisms of SARS-CoV-2 infection and pathogenesis','Bài tổng quan này tóm tắt các cơ chế phân tử của quá trình nhiễm và gây bệnh SARS-CoV-2. Chúng tôi thảo luận về cơ chế xâm nhập của virus, bao gồm liên kết thụ thể ACE2 và kích hoạt protein S, cũng như cơ chế phân tử của phản ứng miễn dịch và bệnh nặng. Hiểu biết về các cơ chế này rất quan trọng để phát triển các chiến lược điều trị và phòng ngừa.','/uploads/sars_cov2_mechanisms.pdf','2026-04-24 11:30:00',22,'completed',60,NULL,'2026-04-24 11:31:00'),
(16,7,'Bitcoin: A Peer-to-Peer Electronic Cash System','Một hệ thống tiền điện tử hoàn toàn ngang hàng cho phép gửi thanh toán trực tuyến từ bên này sang bên kia mà không cần thông qua bất kỳ tổ chức tài chính nào. Chữ ký số giải quyết một phần vấn đề, nhưng lợi ích chính bị mất đi nếu vẫn cần một bên đáng tin cậy để ngăn chi tiêu đôi. Chúng tôi đề xuất giải pháp cho vấn đề chi tiêu đôi bằng cách sử dụng mạng ngang hàng.','/uploads/bitcoin_whitepaper.pdf','2026-04-25 08:00:00',9,'completed',22,NULL,'2026-04-25 08:00:22'),
(17,7,'Ethereum: A Next-Generation Smart Contract and Decentralized Application Platform','Satoshi Nakamoto đã phát triển Bitcoin vào năm 2008 như là một ứng dụng đột phá, nhưng giao thức Bitcoin có những giới hạn quan trọng. Ethereum giải quyết những giới hạn này bằng cách cung cấp một blockchain có ngôn ngữ lập trình Turing đầy đủ tích hợp sẵn, cho phép bất kỳ ai cũng có thể viết hợp đồng thông minh và ứng dụng phi tập trung.','/uploads/ethereum_whitepaper.pdf','2026-04-26 09:30:00',36,'completed',88,NULL,'2026-04-26 09:31:28'),
(18,7,'Zero Trust Security: A Framework for Network Architecture and Access Control','Kiến trúc bảo mật Zero Trust loại bỏ khái niệm tin tưởng ngầm định truyền thống và yêu cầu xác thực liên tục của tất cả người dùng và thiết bị. Bài báo này trình bày một framework toàn diện cho kiến trúc Zero Trust, bao gồm các nguyên tắc cơ bản, mô hình triển khai và thách thức thực tế trong việc áp dụng cho doanh nghiệp.','/uploads/zero_trust_framework.pdf','2026-04-27 10:00:00',15,'processing',NULL,NULL,'2026-04-27 10:00:00'),
(19,7,'The Evolution of DevOps: Practices, Tools, and Challenges in Modern Software Development','DevOps đã thay đổi đáng kể cách phần mềm được phát triển và triển khai. Bài nghiên cứu này khảo sát sự phát triển của thực hành DevOps qua các năm, từ các nguyên tắc ban đầu đến các pipeline CI/CD hiện đại. Chúng tôi phân tích 500+ tổ chức về việc áp dụng DevOps, xác định các thực hành tốt nhất và thách thức phổ biến.','/uploads/devops_evolution.pdf','2026-04-28 11:00:00',18,'completed',55,NULL,'2026-04-28 11:00:55'),
(20,7,'Cloud Computing: State-of-the-Art and Research Challenges','Điện toán đám mây đã trở thành nền tảng của hạ tầng CNTT hiện đại. Bài khảo sát này trình bày tổng quan về kiến trúc, mô hình dịch vụ (IaaS, PaaS, SaaS) và mô hình triển khai của điện toán đám mây. Chúng tôi cũng thảo luận về các vấn đề nghiên cứu còn tồn tại, bao gồm bảo mật, quản lý tài nguyên và điện toán biên.','/uploads/cloud_computing_survey.pdf','2026-04-29 09:00:00',25,'completed',72,NULL,'2026-04-29 09:01:12'),
(21,8,'Big Data Analytics: Methods and Applications','Dữ liệu lớn đang thay đổi cách chúng ta hiểu và phân tích thông tin. Bài báo này khảo sát các phương pháp phân tích dữ liệu lớn hiện đại, bao gồm xử lý theo lô với Hadoop MapReduce, xử lý luồng với Apache Spark và Flink, cũng như các kỹ thuật học máy áp dụng trên quy mô lớn. Chúng tôi thảo luận về các ứng dụng thực tế trong y tế, tài chính và giao thông.','/uploads/big_data_analytics.pdf','2026-04-30 08:30:00',22,'completed',63,NULL,'2026-04-30 08:31:03'),
(22,8,'Machine Learning for Beginners: A Comprehensive Introduction','Bài báo này cung cấp một giới thiệu toàn diện về học máy cho người mới bắt đầu. Chúng tôi trình bày các thuật toán học có giám sát cơ bản như hồi quy tuyến tính, cây quyết định và máy vector hỗ trợ; các thuật toán học không có giám sát như phân cụm k-means và PCA; và giới thiệu về mạng nơ-ron sâu. Mỗi thuật toán được minh họa bằng ví dụ thực tế.','/uploads/ml_beginners.pdf','2026-05-01 09:00:00',28,'completed',80,NULL,'2026-05-01 09:01:20'),
(23,8,'Deep Learning with PyTorch: A Complete Tutorial','Hướng dẫn toàn diện về deep learning sử dụng framework PyTorch. Bài báo bao gồm từ các khái niệm cơ bản về tensor và autograd, đến việc xây dựng và huấn luyện các mạng nơ-ron sâu phức tạp. Chúng tôi trình bày các kiến trúc CNN cho thị giác máy tính, RNN/LSTM cho xử lý chuỗi và Transformer cho NLP, với code mẫu cho từng chủ đề.','/uploads/pytorch_tutorial.pdf','2026-05-02 10:00:00',35,'failed',45,'Lỗi trích xuất: PDF bị lỗi font, không thể trích xuất văn bản.','2026-05-02 10:00:45'),
(24,8,'Computer Vision: Object Detection and Recognition Algorithms','Bài khảo sát này trình bày tổng quan về các thuật toán phát hiện và nhận dạng đối tượng trong ảnh. Từ các phương pháp truyền thống như HOG + SVM đến các phương pháp deep learning hiện đại như R-CNN, YOLO và SSD. Chúng tôi so sánh độ chính xác và tốc độ suy luận của các phương pháp này trên các bộ dữ liệu chuẩn như MS COCO và Pascal VOC.','/uploads/object_detection_survey.pdf','2026-05-03 14:00:00',30,'completed',87,NULL,'2026-05-03 14:01:27'),
(25,8,'Reinforcement Learning: An Introduction and Recent Advances','Học tăng cường là một trong ba paradigm học máy cơ bản, trong đó tác nhân học bằng cách tương tác với môi trường. Bài báo này giới thiệu các khái niệm cơ bản của RL như MDP, Q-learning và policy gradient, sau đó trình bày các tiến bộ gần đây bao gồm deep Q-networks (DQN), proximal policy optimization (PPO) và các ứng dụng trong game, robot và tự lái xe.','/uploads/rl_advances.pdf','2026-05-04 09:30:00',24,'uploaded',NULL,NULL,'2026-05-04 09:30:00'),
(26,9,'Climate Change 2022: Impacts, Adaptation and Vulnerability','Báo cáo đánh giá của IPCC này tổng hợp bằng chứng về tác động của biến đổi khí hậu trên toàn thế giới. Báo cáo ghi lại thiệt hại và tổn thất hiện nay và dự báo rủi ro trong tương lai, đồng thời đánh giá khả năng thích nghi của hệ thống con người và tự nhiên. Kết quả cho thấy ngay cả khi đạt mục tiêu 1,5°C, rủi ro khí hậu vẫn đáng kể.','/uploads/ipcc_report_2022.pdf','2026-05-05 10:00:00',60,'completed',165,NULL,'2026-05-05 10:02:45'),
(27,9,'Renewable Energy Transition: Solar and Wind Power Economics','Bài nghiên cứu này phân tích kinh tế của quá trình chuyển đổi sang năng lượng tái tạo, tập trung vào điện mặt trời và điện gió. Chúng tôi trình bày xu hướng giảm chi phí đáng kể trong thập kỷ qua — chi phí điện mặt trời đã giảm 89% và điện gió ngoài khơi giảm 70% từ 2010 đến 2020. Phân tích cho thấy năng lượng tái tạo hiện có thể cạnh tranh với nhiên liệu hóa thạch ở hầu hết các thị trường.','/uploads/renewable_energy_economics.pdf','2026-05-06 09:00:00',14,'completed',40,NULL,'2026-05-06 09:00:40'),
(28,9,'Electric Vehicles and Grid Integration: Technical Challenges','Xe điện (EV) đang được áp dụng nhanh chóng, đặt ra những thách thức mới cho lưới điện. Bài báo này phân tích các thách thức kỹ thuật của việc tích hợp số lượng lớn xe điện vào hệ thống điện: tác động đến tải đỉnh, yêu cầu hạ tầng sạc, khả năng phản hồi nhu cầu thông minh (V2G) và quản lý lưới điện thông minh.','/uploads/ev_grid_integration.pdf','2026-05-07 11:00:00',20,'completed',58,NULL,'2026-05-07 11:00:58'),
(29,9,'Circular Economy: Principles, Frameworks and Policy Implications','Kinh tế tuần hoàn đề xuất một mô hình kinh doanh thay thế cho nền kinh tế tuyến tính truyền thống. Bài báo này trình bày các nguyên tắc cốt lõi của kinh tế tuần hoàn, bao gồm thiết kế không có chất thải, giữ nguyên giá trị vật liệu và tái sinh hệ thống tự nhiên. Chúng tôi phân tích các case study thực tế từ các công ty như Renault, Caterpillar và Philips.','/uploads/circular_economy.pdf','2026-05-08 09:00:00',22,'completed',65,NULL,'2026-05-08 09:01:05'),
(30,9,'Global macroeconomic outlook 2025: Navigating uncertainty','Triển vọng kinh tế vĩ mô toàn cầu năm 2025 đối mặt với nhiều bất ổn. Báo cáo này của IMF phân tích các yếu tố chính ảnh hưởng đến tăng trưởng kinh tế toàn cầu, bao gồm áp lực lạm phát dai dẳng, chính sách tiền tệ thắt chặt ở các nền kinh tế phát triển, căng thẳng địa chính trị và rủi ro nợ công. Dự báo tăng trưởng GDP toàn cầu ở mức 3,1% năm 2025.','/uploads/imf_outlook_2025.pdf','2026-05-09 14:00:00',45,'processing',NULL,NULL,'2026-05-09 14:00:00'),
(31,10,'The Value Investor: Security Analysis and Intrinsic Value','Đầu tư giá trị là phương pháp đầu tư dựa trên phân tích cơ bản để tìm kiếm cổ phiếu được định giá thấp hơn giá trị nội tại. Bài báo này hệ thống hóa các nguyên tắc của Benjamin Graham và Warren Buffett về phân tích bảo đảm và đầu tư giá trị, đồng thời cập nhật các phương pháp định giá cho thị trường hiện đại, bao gồm phân tích DCF và EV/EBITDA.','/uploads/value_investing.pdf','2026-05-01 10:00:00',32,'completed',89,NULL,'2026-05-01 10:01:29'),
(32,10,'DeFi: Decentralized Finance Protocols and Risk Analysis','Tài chính phi tập trung (DeFi) đã tạo ra một hệ sinh thái tài chính mới trên blockchain. Bài báo này cung cấp phân tích toàn diện về các giao thức DeFi chính bao gồm DEX (Uniswap, Curve), lending protocols (Aave, Compound) và yield farming. Chúng tôi phân tích rủi ro đặc thù của DeFi như smart contract vulnerabilities, oracle manipulation và liquidation cascades.','/uploads/defi_protocols.pdf','2026-05-02 09:00:00',28,'completed',79,NULL,'2026-05-02 09:01:19'),
(33,10,'Behavioral Economics and Decision Making Under Uncertainty','Kinh tế học hành vi kết hợp các hiểu biết từ tâm lý học vào phân tích kinh tế. Bài báo này tổng hợp các phát hiện chính về ra quyết định dưới điều kiện bất định, bao gồm lý thuyết triển vọng của Kahneman và Tversky, các bias nhận thức phổ biến và ảnh hưởng của chúng đến thị trường tài chính. Chúng tôi thảo luận về các hàm ý chính sách và thiết kế tổ chức.','/uploads/behavioral_economics.pdf','2026-05-03 11:00:00',18,'completed',51,NULL,'2026-05-03 11:00:51'),
(34,11,'Molecular Biology of Cancer: Mechanisms and Targeted Therapies','Ung thư là kết quả của sự tích lũy các đột biến di truyền và thay đổi epigenetic. Bài tổng quan này mô tả các cơ chế phân tử của ung thư học, bao gồm các gen ung thư, gen ức chế khối u, con đường tín hiệu bị rối loạn và cơ chế né tránh miễn dịch. Chúng tôi tập trung vào các liệu pháp nhắm mục tiêu đã được FDA phê duyệt và các liệu pháp miễn dịch mới nổi.','/uploads/cancer_molecular_biology.pdf','2026-04-20 08:00:00',35,'completed',98,NULL,'2026-04-20 08:01:38'),
(35,11,'The Gut Microbiome and Mental Health: Gut-Brain Axis','Trục ruột-não là con đường giao tiếp hai chiều giữa hệ vi sinh vật đường ruột và não bộ. Nghiên cứu gần đây cho thấy rối loạn hệ vi sinh vật đường ruột có liên quan đến các bệnh tâm thần như trầm cảm, lo lắng và rối loạn phổ tự kỷ. Bài tổng quan này tóm tắt bằng chứng từ nghiên cứu tiền lâm sàng và lâm sàng, đồng thời thảo luận về các can thiệp trị liệu tiềm năng.','/uploads/gut_brain_axis.pdf','2026-04-21 09:30:00',20,'completed',58,NULL,'2026-04-21 09:30:58'),
(36,11,'Data Science for Healthcare: Applications and Case Studies','Khoa học dữ liệu đang cách mạng hóa y tế. Bài báo này trình bày các ứng dụng của học máy và phân tích dữ liệu lớn trong y tế, bao gồm chẩn đoán hình ảnh y tế bằng deep learning, dự đoán nguy cơ bệnh nhân, tối ưu hóa điều trị cá nhân hóa và quản lý bệnh viện. Chúng tôi thảo luận về các thách thức về quyền riêng tư dữ liệu và triển khai lâm sàng.','/uploads/data_science_healthcare.pdf','2026-04-22 10:00:00',26,'failed',3,'Lỗi trích xuất: PDF là dạng ảnh scan không chứa văn bản.','2026-04-22 10:00:03'),
(37,12,'Rise of Rome: The Political and Military History of the Roman Republic','Lịch sử chính trị và quân sự của Cộng hòa La Mã là câu chuyện về sự nổi lên của một đế chế từ một thành phố nhỏ ven bờ sông Tiber. Bài báo này phân tích các yếu tố then chốt dẫn đến sự mở rộng của La Mã: tổ chức quân sự ưu việt, hệ thống chính trị linh hoạt và khả năng đồng hóa các dân tộc bị chinh phục. Chúng tôi xem xét các cuộc chiến Punic và sự chuyển đổi sang Đế chế.','/uploads/rise_of_rome.pdf','2026-04-25 09:00:00',40,'completed',112,NULL,'2026-04-25 09:01:52'),
(38,12,'The Industrial Revolution: Social and Economic Transformations','Cách mạng Công nghiệp (1760-1840) là một trong những sự kiện biến đổi nhất trong lịch sử loài người. Bài nghiên cứu này phân tích các nguyên nhân, quá trình và hệ quả của Cách mạng Công nghiệp tại Anh và sự lan rộng ra châu Âu và Bắc Mỹ. Chúng tôi tập trung vào các thay đổi trong cơ cấu kinh tế, xã hội và điều kiện sống của tầng lớp lao động.','/uploads/industrial_revolution.pdf','2026-04-26 10:30:00',30,'completed',83,NULL,'2026-04-26 10:31:23'),
(39,12,'The Cold War: Origins, Confrontations and Legacy','Chiến tranh Lạnh (1947-1991) là cuộc cạnh tranh địa chính trị, kinh tế và tư tưởng giữa Hoa Kỳ và Liên Xô. Bài báo này phân tích nguồn gốc của Chiến tranh Lạnh từ sự bất đồng về trật tự thế giới hậu Thế chiến II, các cuộc đối đầu chính như Khủng hoảng tên lửa Cuba, Chiến tranh Triều Tiên và Việt Nam, đến sự sụp đổ của Liên Xô năm 1991.','/uploads/cold_war_history.pdf','2026-04-27 08:00:00',35,'completed',97,NULL,'2026-04-27 08:01:37'),
(40,12,'Stoic Philosophy: From Ancient Wisdom to Modern Applications','Triết học Khắc kỷ, xuất phát từ Athens vào thế kỷ 3 TCN, đang trải qua sự phục hưng trong thế giới hiện đại. Bài báo này trình bày các nguyên tắc cốt lõi của Chủ nghĩa Khắc kỷ từ Epictetus, Marcus Aurelius và Seneca, bao gồm sự phân biệt giữa điều có thể kiểm soát và không, thực hành thiền định Stoic và áp dụng trong tâm lý học hiện đại.','/uploads/stoic_philosophy.pdf','2026-04-28 11:00:00',22,'completed',60,NULL,'2026-04-28 11:01:00'),
(41,13,'Digital Education in the Post-Pandemic Era: Trends and Challenges','Đại dịch COVID-19 đã thúc đẩy mạnh mẽ chuyển đổi số trong giáo dục. Bài báo này phân tích các xu hướng giáo dục số hậu đại dịch, bao gồm học tập kết hợp (blended learning), MOOC, gamification và AI trong giáo dục. Chúng tôi khảo sát 1.200 giáo viên và 3.500 học sinh tại 10 quốc gia để đánh giá hiệu quả và thách thức của các phương pháp này.','/uploads/digital_education.pdf','2026-05-01 08:00:00',24,'completed',68,NULL,'2026-05-01 08:01:08'),
(42,13,'Behavioral Psychology: Cognitive Biases and Decision Making','Tâm lý học hành vi nghiên cứu cách con người thực sự ra quyết định, thường khác biệt đáng kể với mô hình con người lý trí. Bài báo này tổng hợp nghiên cứu về các bias nhận thức phổ biến: confirmation bias, anchoring effect, availability heuristic và sunk cost fallacy. Chúng tôi thảo luận về các can thiệp dựa trên bằng chứng để cải thiện quá trình ra quyết định.','/uploads/cognitive_biases.pdf','2026-05-02 09:30:00',20,'completed',57,NULL,'2026-05-02 09:30:57'),
(43,13,'Generative AI: Capabilities, Limitations and Societal Impact','Trí tuệ nhân tạo tạo sinh (GenAI) đã đạt được những bước tiến vượt bậc với các mô hình như GPT-4, Claude và Gemini. Bài báo này đánh giá toàn diện các khả năng hiện tại của GenAI trong tạo văn bản, hình ảnh, code và âm nhạc; phân tích các hạn chế như hallucination, bias và thiếu hiểu biết nhân quả; và thảo luận về tác động xã hội bao gồm ảnh hưởng đến thị trường lao động.','/uploads/generative_ai_impact.pdf','2026-05-03 10:00:00',28,'completed',79,NULL,'2026-05-03 10:01:19'),
(44,14,'Natural Language Processing: From Rule-based to Neural Methods','Xử lý ngôn ngữ tự nhiên đã trải qua sự chuyển đổi mạnh mẽ từ các phương pháp dựa trên quy tắc sang học máy và gần đây là deep learning. Bài tổng quan này theo dõi lịch sử phát triển của NLP từ parser sớm đến mô hình n-gram thống kê, máy vector hỗ trợ, mạng LSTM và cuối cùng là kiến trúc Transformer hiện đại. Chúng tôi đánh giá các bộ dữ liệu và thước đo đánh giá chuẩn.','/uploads/nlp_history.pdf','2026-05-04 09:00:00',26,'completed',73,NULL,'2026-05-04 09:01:13'),
(45,14,'Blockchain Technology: Architecture, Consensus and Applications','Công nghệ blockchain là nền tảng của tiền điện tử và hợp đồng thông minh. Bài báo này trình bày kiến trúc kỹ thuật của blockchain, các cơ chế đồng thuận (PoW, PoS, BFT), tính bảo mật và khả năng mở rộng. Chúng tôi phân tích các ứng dụng ngoài tiền tệ bao gồm chuỗi cung ứng, hệ thống y tế, bỏ phiếu điện tử và quản lý bản quyền.','/uploads/blockchain_architecture.pdf','2026-05-05 10:00:00',30,'completed',84,NULL,'2026-05-05 10:01:24'),
(46,14,'Neural Network Optimization: Gradient Descent and Beyond','Tối ưu hóa mạng nơ-ron sâu là thách thức cốt lõi trong học máy. Bài báo này phân tích các thuật toán tối ưu hóa từ gradient descent cơ bản đến các biến thể hiện đại như Adam, RMSprop và AdaGrad. Chúng tôi thảo luận về các vấn đề như saddle points, vanishing/exploding gradients, batch normalization và các kỹ thuật như learning rate scheduling và warmup.','/uploads/nn_optimization.pdf','2026-05-06 08:30:00',22,'failed',8,'Lỗi dung lượng: File PDF vượt quá giới hạn kích thước xử lý (500MB).','2026-05-06 08:30:08'),
(47,15,'Vaccine Development: From Research to Clinical Trials','Quá trình phát triển vaccine từ nghiên cứu cơ bản đến phê duyệt thường mất 10-15 năm. Bài báo này mô tả quy trình phát triển vaccine hiện đại, bao gồm các giai đoạn nghiên cứu tiền lâm sàng, thử nghiệm lâm sàng pha I-III và đánh giá hậu thị trường. Chúng tôi phân tích các nền tảng vaccine mới như mRNA, vector virus và nanoparticle protein.','/uploads/vaccine_development.pdf','2026-05-03 09:00:00',20,'completed',56,NULL,'2026-05-03 09:00:56'),
(48,15,'Sea Level Rise and Coastal Vulnerability: A Global Assessment','Mực nước biển đang tăng với tốc độ nhanh nhất trong lịch sử đo đạc. Báo cáo này đánh giá mức độ dễ bị tổn thương của các vùng ven biển toàn cầu trước nguy cơ dâng mực nước biển do biến đổi khí hậu. Chúng tôi phân tích dữ liệu vệ tinh và mô hình khí hậu để dự báo tác động đến đến năm 2100, tập trung vào các thành phố ven biển và đảo quốc nhỏ.','/uploads/sea_level_rise.pdf','2026-05-04 10:00:00',18,'completed',50,NULL,'2026-05-04 10:00:50'),
(49,16,'Quantum Computing: Principles and Potential Applications','Máy tính lượng tử sử dụng các nguyên lý của cơ học lượng tử để thực hiện các phép tính mà máy tính cổ điển không thể xử lý hiệu quả. Bài báo này giải thích các khái niệm cơ bản như qubit, superposition, entanglement và quantum gates. Chúng tôi phân tích các thuật toán lượng tử tiêu biểu (Shor, Grover) và các ứng dụng tiềm năng trong mật mã học, tối ưu hóa và mô phỏng phân tử.','/uploads/quantum_computing.pdf','2026-05-05 08:00:00',34,'completed',94,NULL,'2026-05-05 08:01:34'),
(50,16,'Cybersecurity Threats in the Age of AI: New Challenges and Defenses','AI đang thay đổi cả cách tấn công mạng lẫn cách phòng thủ. Bài báo này phân tích các mối đe dọa an ninh mạng mới do AI tạo ra, bao gồm tấn công adversarial, deepfake, tự động hóa khai thác lỗ hổng và tấn công xã hội có AI. Đồng thời, chúng tôi trình bày các phương pháp phòng thủ dựa trên AI như phát hiện bất thường, phân tích hành vi và hệ thống phản ứng tự động.','/uploads/ai_cybersecurity.pdf','2026-05-06 10:00:00',25,'completed',70,NULL,'2026-05-06 10:01:10'),
(51,21,'The Economics of Artificial Intelligence: Productivity, Inequality and Policy Responses',
'Trí tuệ nhân tạo đang trở thành động lực tăng trưởng kinh tế thế hệ tiếp theo. Bài nghiên cứu này của Erik Brynjolfsson và cộng sự phân tích tác động kinh tế vĩ mô của AI: đóng góp vào năng suất lao động, phân phối thu nhập và các hàm ý chính sách. Dữ liệu từ 800 doanh nghiệp Mỹ giai đoạn 2017-2023 cho thấy những doanh nghiệp áp dụng AI sớm đạt mức tăng năng suất 15-22% sau 3 năm, song tác động bất đối xứng giữa lao động kỹ năng cao và thấp.',
'/uploads/economics_of_ai.pdf','2026-04-11 09:15:00',28,'completed',77,NULL,'2026-04-11 09:16:17'),
 
(52,21,'ESG Investing: Evidence, Debates and Long-Term Performance',
'Đầu tư ESG (Environmental, Social, Governance) đã tăng trưởng từ 22 nghìn tỷ USD năm 2016 lên hơn 40 nghìn tỷ USD năm 2024. Bài meta-analysis này tổng hợp 1.200 nghiên cứu học thuật về mối quan hệ giữa điểm ESG và lợi nhuận tài chính. Kết quả: 58% nghiên cứu tìm thấy mối tương quan dương, 13% tương quan âm và 29% không có ý nghĩa thống kê — cho thấy bức tranh phức tạp hơn các tuyên bố marketing.',
'/uploads/esg_investing_evidence.pdf','2026-04-18 14:00:00',22,'completed',63,NULL,'2026-04-18 14:01:03'),
 
-- === Trương Thị Quỳnh (id=22) — Ngôn ngữ học, dịch thuật ===
(53,22,'Machine Translation Quality Estimation: Progress and Remaining Challenges',
'Đánh giá chất lượng dịch máy (Quality Estimation — QE) là bài toán dự đoán chất lượng bản dịch mà không cần bản dịch tham chiếu của người. Bài khảo sát này tổng hợp tiến bộ trong QE từ các tính năng thống kê truyền thống đến các mô hình BERT-based hiện đại như TransQuest và CometKiwi. Chúng tôi phân tích kết quả WMT 2021-2023 và thảo luận về khoảng cách còn lại giữa QE tự động và đánh giá của chuyên gia ngôn ngữ.',
'/uploads/mt_quality_estimation.pdf','2026-04-22 09:30:00',18,'completed',50,NULL,'2026-04-22 09:30:50'),
 
(54,22,'Low-Resource Neural Machine Translation: Techniques for Vietnamese and Southeast Asian Languages',
'Tiếng Việt và các ngôn ngữ Đông Nam Á là ngôn ngữ tài nguyên thấp (low-resource) trong dịch máy nơ-ron — thiếu dữ liệu song ngữ song song chất lượng cao. Bài báo này trình bày các kỹ thuật hiệu quả cho low-resource NMT: transfer learning từ ngôn ngữ tương đồng, back-translation với dữ liệu đơn ngữ, data augmentation và mBERT/XLM-R fine-tuning. Thử nghiệm trên cặp Việt-Anh và Việt-Khmer cho thấy cải thiện BLEU 8-12 điểm so với baseline.',
'/uploads/low_resource_nmt_vietnamese.pdf','2026-04-30 10:00:00',24,'completed',67,NULL,'2026-04-30 10:01:07'),
 
-- === Đặng Quốc Hiếu (id=23) — Kỹ thuật điện tử, IoT ===
(55,23,'Edge AI: Deploying Machine Learning Models on Resource-Constrained Devices',
'Edge AI đưa suy luận học máy trực tiếp về thiết bị biên (smartphone, MCU, FPGA) thay vì phụ thuộc vào cloud. Bài báo này trình bày các kỹ thuật nén mô hình — pruning, quantization (INT8/INT4), knowledge distillation và neural architecture search — cho phép triển khai mô hình deep learning trên thiết bị với RAM <1GB. Benchmark trên Raspberry Pi 4, STM32H7 và NVIDIA Jetson Nano với các tác vụ phân loại hình ảnh, phát hiện đối tượng và wake word detection.',
'/uploads/edge_ai_deployment.pdf','2026-05-01 08:00:00',26,'completed',72,NULL,'2026-05-01 08:01:12'),
 
(56,23,'5G Network Slicing for Industrial IoT: Architecture and QoS Guarantees',
'Phân mảnh mạng (Network Slicing) trong 5G cho phép tạo ra nhiều mạng ảo logic trên cùng cơ sở hạ tầng vật lý, mỗi mạng với các đặc tính QoS riêng biệt. Bài báo này thiết kế kiến trúc network slicing cho Industrial IoT (IIoT) trong nhà máy thông minh: ultra-low latency slice (<1ms) cho điều khiển robot, massive IoT slice cho cảm biến và enhanced broadband slice cho camera giám sát. Đánh giá thông qua mô phỏng ns-3 với 10.000 thiết bị đồng thời.',
'/uploads/5g_network_slicing_iiot.pdf','2026-05-08 11:00:00',20,'processing',NULL,NULL,'2026-05-08 11:00:00'),
 
-- === Lê Thị Phương (id=24) — Y tế công cộng ===
(57,24,'Mental Health Crisis in Vietnamese Youth: Prevalence, Risk Factors and Intervention Strategies',
'Sức khỏe tâm thần thanh thiếu niên Việt Nam đang trở thành vấn đề y tế công cộng nghiêm trọng. Khảo sát toàn quốc trên 12.450 học sinh THCS và THPT (2023-2024) cho thấy 32,6% có triệu chứng lo lắng mức độ vừa-nặng và 19,8% có triệu chứng trầm cảm. Các yếu tố nguy cơ: áp lực học tập, bắt nạt học đường và sử dụng mạng xã hội >4 giờ/ngày. Bài báo đề xuất khung can thiệp đa tầng: trường học, gia đình và cộng đồng.',
'/uploads/mental_health_vietnamese_youth.pdf','2026-04-15 10:00:00',30,'completed',84,NULL,'2026-04-15 10:01:24'),
 
(58,24,'Telemedicine Adoption in Rural Vietnam: Barriers, Facilitators and Health Outcomes',
'Y tế từ xa (telemedicine) có tiềm năng thu hẹp khoảng cách tiếp cận dịch vụ y tế giữa đô thị và nông thôn Việt Nam. Nghiên cứu hỗn hợp này phân tích việc áp dụng telemedicine tại 45 trạm y tế xã ở 6 tỉnh miền núi phía Bắc và đồng bằng sông Cửu Long. Kết quả: 68% bệnh nhân hài lòng với tư vấn từ xa; tỷ lệ chẩn đoán đúng đạt 82% so với khám trực tiếp. Rào cản chính: kết nối internet yếu (38% trạm y tế), thiếu kỹ năng số của y bác sĩ và e ngại của bệnh nhân cao tuổi.',
'/uploads/telemedicine_rural_vietnam.pdf','2026-04-28 13:30:00',25,'completed',70,NULL,'2026-04-28 13:31:10'),
 
-- === Nguyễn Anh Sơn (id=25) — Khoa học máy tính, bảo mật ===
(59,25,'Federated Learning: Privacy-Preserving Distributed Machine Learning',
'Federated Learning (FL) cho phép huấn luyện mô hình học máy trên dữ liệu phân tán mà không cần tập trung dữ liệu thô về máy chủ — giải quyết xung đột giữa học máy và quyền riêng tư dữ liệu. Bài báo này trình bày thuật toán FedAvg, các biến thể FedProx và SCAFFOLD để xử lý Non-IID data và client heterogeneity, đồng thời phân tích các mối đe dọa (gradient inversion, model poisoning) và phòng thủ (differential privacy, secure aggregation). Ứng dụng thực tế: bàn phím dự đoán Google, phát hiện gian lận ngân hàng và chẩn đoán y tế liên bệnh viện.',
'/uploads/federated_learning_privacy.pdf','2026-04-20 09:00:00',32,'completed',89,NULL,'2026-04-20 09:01:29'),
 
(60,25,'Post-Quantum Cryptography: NIST Standards and Migration Challenges',
'Thuật toán Shor trên máy tính lượng tử có thể phá vỡ RSA và ECC trong thời gian đa thức — đe dọa toàn bộ hạ tầng bảo mật internet hiện tại. NIST đã chính thức chuẩn hóa 4 thuật toán mật mã hậu lượng tử vào năm 2024: CRYSTALS-Kyber (trao đổi khóa), CRYSTALS-Dilithium và FALCON (chữ ký số), và SPHINCS+ (dự phòng). Bài báo phân tích hiệu suất các thuật toán này, thách thức di chuyển hệ thống legacy và lộ trình triển khai cho doanh nghiệp.',
'/uploads/post_quantum_cryptography.pdf','2026-05-02 10:00:00',28,'completed',78,NULL,'2026-05-02 10:01:18'),
 
-- === Hoàng Thị Thúy (id=26) — Giáo dục, sư phạm ===
(61,26,'Adaptive Learning Systems: Personalized Education through AI',
'Hệ thống học tập thích nghi (Adaptive Learning Systems — ALS) sử dụng AI để cá nhân hóa lộ trình học tập cho từng học sinh dựa trên năng lực, phong cách học và tiến độ. Bài báo này so sánh 5 hệ thống ALS thương mại (Khan Academy, Duolingo, ALEKS, Smart Sparrow và Khanmigo) và 3 nền tảng nghiên cứu, đánh giá hiệu quả trên 15.000 học sinh qua 2 năm học. Kết quả: ALS cải thiện điểm số trung bình 18% và giảm tỷ lệ bỏ học 23% so với phương pháp truyền thống.',
'/uploads/adaptive_learning_ai.pdf','2026-04-16 08:30:00',22,'completed',60,NULL,'2026-04-16 08:31:00'),
 
(62,26,'Project-Based Learning in STEM Education: A Meta-Analysis',
'Học tập dựa trên dự án (Project-Based Learning — PBL) trong STEM đã được nghiên cứu rộng rãi nhưng bằng chứng về hiệu quả còn mâu thuẫn. Meta-analysis này tổng hợp 147 nghiên cứu giai đoạn 2010-2023 với tổng cộng 28.400 học sinh từ 18 quốc gia. Kết quả: effect size tổng thể d = 0,47 (trung bình-lớn), tác động mạnh nhất ở kỹ năng giải quyết vấn đề (d = 0,62) và hợp tác nhóm (d = 0,55), yếu hơn ở kiến thức hàn lâm thuần túy (d = 0,31). PBL hiệu quả nhất với học sinh trung học cơ sở.',
'/uploads/pbl_stem_meta_analysis.pdf','2026-05-04 14:00:00',19,'completed',53,NULL,'2026-05-04 14:00:53'),
 
-- === Trần Văn Đức (id=27) — Tự động hóa, robot ===
(63,27,'Autonomous Mobile Robots in Warehouse Logistics: Navigation, Planning and Safety',
'Robot tự hành trong kho hàng (Autonomous Mobile Robots — AMR) đang thay đổi ngành logistics. Bài báo này trình bày kiến trúc hệ thống AMR hoàn chỉnh: định vị và lập bản đồ đồng thời (SLAM) với LiDAR + camera, lập kế hoạch đường đi A* và Dynamic Window Approach, phối hợp đa robot tránh va chạm và giao tiếp với WMS. Đánh giá hệ thống 50 AMR tại kho Amazon Robotics: throughput 3.200 items/giờ, tăng 240% so với quy trình thủ công, với 0 sự cố an toàn trong 18 tháng vận hành.',
'/uploads/amr_warehouse_logistics.pdf','2026-04-17 10:00:00',27,'completed',76,NULL,'2026-04-17 10:01:16'),
 
(64,27,'Digital Twin Technology for Smart Manufacturing',
'Bản sao kỹ thuật số (Digital Twin) là mô hình ảo thời gian thực của hệ thống vật lý — từng máy móc đến toàn bộ nhà máy — đồng bộ liên tục qua dữ liệu IoT. Bài báo này mô tả kiến trúc Digital Twin cho nhà máy thông minh: tích hợp dữ liệu cảm biến, mô phỏng vật lý (FEM, CFD), mô hình học máy dự đoán sự cố và tối ưu vận hành. Case study tại nhà máy Siemens Amberg: giảm 75% tỷ lệ lỗi sản phẩm, tiết kiệm 30% thời gian giao hàng và bảo trì dự báo giảm downtime 50%.',
'/uploads/digital_twin_manufacturing.pdf','2026-04-24 11:00:00',23,'completed',65,NULL,'2026-04-24 11:01:05'),
 
-- === Bùi Thị Linh (id=28) — Sinh học phân tử ===
(65,28,'Single-Cell RNA Sequencing: Technologies, Analysis Methods and Biological Insights',
'Giải trình tự RNA đơn tế bào (scRNA-seq) cho phép đo lường biểu hiện gene ở độ phân giải từng tế bào, cách mạng hóa hiểu biết về sự đa dạng tế bào trong mô. Bài khảo sát này so sánh các nền tảng scRNA-seq (10x Chromium, Smart-seq2, Drop-seq, SPLiT-seq), pipeline phân tích (Seurat, Scanpy) và các phương pháp tính toán cho clustering, trajectory analysis và cell-cell communication. Ứng dụng: phát hiện loại tế bào mới trong não người, lập bản đồ miễn dịch khối u và phân loại ung thư máu.',
'/uploads/scrna_seq_methods.pdf','2026-04-19 09:00:00',38,'completed',105,NULL,'2026-04-19 09:01:45'),
 
(66,28,'Epigenetics and Gene Regulation: DNA Methylation, Histone Modification and Chromatin Remodeling',
'Epigenetics nghiên cứu các thay đổi biểu hiện gene không phụ thuộc vào trình tự DNA. Bài tổng quan này mô tả ba cơ chế epigenetic chính: methyl hóa DNA (CpG methylation và vai trò trong im lặng gene), biến đổi histone (acetylation/methylation/phosphorylation) và tái mô hình hóa chromatin (complex SWI/SNF). Sai lệch epigenetic trong ung thư, lão hóa và bệnh thần kinh. Liệu pháp nhắm mục tiêu epigenetics: DNMT inhibitors (azacitidine) và HDAC inhibitors đã được FDA phê duyệt.',
'/uploads/epigenetics_gene_regulation.pdf','2026-05-06 13:00:00',29,'completed',81,NULL,'2026-05-06 13:01:21'),
 
-- === Võ Minh Hùng (id=29) — Nông nghiệp, môi trường ===
(67,29,'Precision Agriculture: IoT, Drones and AI for Sustainable Farming',
'Nông nghiệp chính xác (Precision Agriculture) ứng dụng công nghệ để tối ưu hóa đầu vào (nước, phân bón, thuốc trừ sâu) và tối đa hóa sản lượng. Bài báo này trình bày kiến trúc hệ thống nông nghiệp chính xác hoàn chỉnh: mạng cảm biến đất và thời tiết LoRaWAN, drone đa phổ cho phát hiện bệnh cây và thiếu dinh dưỡng, mô hình AI dự đoán sản lượng từ ảnh vệ tinh Sentinel-2. Thử nghiệm tại 120 ha lúa tại Cần Thơ và Sóc Trăng: giảm 30% lượng nước tưới, 25% phân bón và tăng 12% năng suất.',
'/uploads/precision_agriculture_vn.pdf','2026-04-26 08:00:00',24,'completed',68,NULL,'2026-04-26 08:01:08'),
 
(68,29,'Mangrove Ecosystem Services and Restoration in the Mekong Delta',
'Hệ sinh thái rừng ngập mặn đồng bằng sông Cửu Long đã mất hơn 80% diện tích trong 50 năm qua do nuôi tôm, đô thị hóa và biến đổi khí hậu. Bài báo này định lượng các dịch vụ hệ sinh thái của rừng ngập mặn: cô lập carbon (8-12 tấn CO₂/ha/năm — cao gấp 3 lần rừng nhiệt đới), bảo vệ bờ biển (giảm 70% năng lượng sóng), sinh kế thủy sản và lọc nước. Phân tích chi phí-lợi ích của 15 dự án phục hồi tại Cà Mau, Kiên Giang và Bến Tre giai đoạn 2015-2023.',
'/uploads/mangrove_mekong_delta.pdf','2026-05-03 09:30:00',26,'completed',73,NULL,'2026-05-03 09:31:13'),
 
-- === Đỗ Thị Mai (id=30) — Kiến trúc, đô thị ===
(69,30,'Smart City Infrastructure: Data Platforms, Citizen Services and Urban Analytics',
'Thành phố thông minh (Smart City) tích hợp công nghệ số để nâng cao chất lượng dịch vụ công và hiệu quả quản lý đô thị. Bài báo này phân tích kiến trúc nền tảng dữ liệu thành phố thông minh: thu thập dữ liệu từ camera CCTV, cảm biến không khí, đồng hồ điện thông minh và dịch vụ công trực tuyến; xử lý trên City OS; và ứng dụng trong tối ưu giao thông, dự báo nhu cầu điện và phát hiện rác bất hợp pháp. Case study: Singapore, Amsterdam và Hà Nội thí điểm.',
'/uploads/smart_city_infrastructure.pdf','2026-05-05 11:00:00',32,'uploaded',NULL,NULL,'2026-05-05 11:00:00'),
 
(70,30,'Urban Heat Island Effect: Causes, Measurement and Mitigation in Vietnamese Cities',
'Hiệu ứng đảo nhiệt đô thị (Urban Heat Island — UHI) khiến thành phố nóng hơn vùng nông thôn xung quanh 2-8°C do mật độ xây dựng, bề mặt nhân tạo và nhiệt thải từ giao thông và điều hòa không khí. Nghiên cứu này đo lường UHI tại Hà Nội và TP.HCM bằng dữ liệu Landsat 8 và trạm khí tượng mặt đất giai đoạn 2016-2024. Mô hình dự báo UHI năm 2050 với các kịch bản phát triển đô thị khác nhau. Các giải pháp giảm thiểu: mái nhà xanh, tường cây và mở rộng cây đường phố.',
'/uploads/urban_heat_island_vietnam.pdf','2026-05-09 10:00:00',21,'completed',59,NULL,'2026-05-09 10:00:59'),
 
-- === Nguyễn Đình Kiên (id=31) — Vật liệu, hóa học ===
(71,31,'Battery Technology for Electric Vehicles: Lithium-Ion, Solid-State and Beyond',
'Công nghệ pin là yếu tố then chốt quyết định tốc độ chuyển đổi xe điện. Bài báo này so sánh toàn diện các hóa học pin: NMC, LFP, NCA (lithium-ion) và pin thể rắn (solid-state) đang phát triển. Phân tích theo 6 tiêu chí: mật độ năng lượng, tuổi thọ chu kỳ, an toàn, chi phí, hiệu suất nhiệt độ thấp và khả năng sạc nhanh. Dự báo: pin thể rắn đạt thương mại hóa quy mô lớn năm 2028-2030 với mật độ năng lượng 400+ Wh/kg, gấp đôi pin lithium-ion hiện tại.',
'/uploads/battery_technology_ev.pdf','2026-04-14 10:00:00',31,'completed',87,NULL,'2026-04-14 10:01:27'),
 
(72,31,'Nanomaterials for Drug Delivery: Liposomes, Nanoparticles and Targeted Therapy',
'Vật liệu nano trong dẫn truyền thuốc cho phép đưa thuốc đến đúng mô đích với nồng độ cao hơn và giảm tác dụng phụ so với thuốc tự do. Bài tổng quan này trình bày các hệ thống nano dẫn truyền thuốc chính: liposome (Doxil — đã FDA phê duyệt), nanoparticle polymer (PLGA), nanoparticle vô cơ (sắt oxide cho MRI và nhiệt trị liệu), nanoparticle lipid (nền tảng vaccine mRNA). Thách thức: tỷ lệ tích lũy khối u chỉ 0,7% liều tiêm — cần chiến lược active targeting cải thiện.',
'/uploads/nanomaterials_drug_delivery.pdf','2026-04-27 14:00:00',27,'failed',12,'Lỗi trích xuất: File PDF được bảo vệ mật khẩu, không thể mở.','2026-04-27 14:00:12'),
 
-- === Phạm Thị Oanh (id=32) — Logistics, chuỗi cung ứng ===
(73,32,'Supply Chain Resilience: Lessons from COVID-19 and Geopolitical Disruptions',
'Đại dịch COVID-19 và căng thẳng địa chính trị (chiến tranh Ukraine, cạnh tranh Mỹ-Trung) đã phơi bày những điểm yếu nghiêm trọng của chuỗi cung ứng toàn cầu. Bài nghiên cứu này phân tích chiến lược xây dựng khả năng phục hồi chuỗi cung ứng dựa trên khảo sát 400 doanh nghiệp sản xuất tại ASEAN. Các chiến lược hiệu quả nhất: đa dạng hóa nhà cung cấp (near-shoring và friend-shoring), xây dựng tồn kho an toàn chiến lược, số hóa visibility chuỗi cung ứng và phát triển kịch bản dự phòng.',
'/uploads/supply_chain_resilience.pdf','2026-04-21 11:00:00',26,'completed',73,NULL,'2026-04-21 11:01:13'),
 
(74,32,'Last-Mile Delivery Optimization: Algorithms and Business Models',
'Giao hàng chặng cuối (last-mile delivery) chiếm 28-53% tổng chi phí logistics nhưng là điểm tiếp xúc quyết định trải nghiệm khách hàng. Bài báo này trình bày các thuật toán tối ưu hóa tuyến đường (Vehicle Routing Problem — VRP) và biến thể thực tế: CVRP với ràng buộc trọng tải, VRPTW với khung thời gian, và thuật toán heuristic (Genetic Algorithm, Ant Colony). Đánh giá các mô hình kinh doanh: hub-and-spoke, crowd-sourced delivery (Lalamove, GrabExpress) và robot giao hàng tự hành trong thành phố.',
'/uploads/last_mile_delivery.pdf','2026-05-07 09:00:00',22,'completed',62,NULL,'2026-05-07 09:01:02'),
 
-- === Lê Văn Dũng (id=33) — Luật, chính sách ===
(75,33,'AI Regulation: Comparing the EU AI Act, US Executive Order and China AI Governance Framework',
'Ba cường quốc AI — EU, Mỹ và Trung Quốc — đang hình thành các khung quản lý AI khác biệt. EU AI Act (2024) phân loại AI theo rủi ro (unacceptable/high/limited/minimal) và áp đặt yêu cầu nghiêm ngặt với AI rủi ro cao (biometric, hạ tầng quan trọng, tư pháp). Lệnh hành pháp Mỹ (2023) tập trung vào an toàn AI và bảo vệ an ninh quốc gia. Trung Quốc có quy định riêng cho recommendation algorithms và generative AI. Bài báo so sánh 12 chiều cạnh pháp lý và hàm ý cho doanh nghiệp toàn cầu.',
'/uploads/ai_regulation_comparison.pdf','2026-04-23 10:00:00',34,'completed',94,NULL,'2026-04-23 10:01:34'),
 
(76,33,'Intellectual Property and Generative AI: Copyright, Authorship and Liability',
'Sự phổ biến của AI tạo sinh đặt ra các câu hỏi pháp lý chưa có tiền lệ về quyền sở hữu trí tuệ. Bài báo này phân tích ba vấn đề pháp lý trọng tâm: (1) Dữ liệu huấn luyện — việc scrape dữ liệu có vi phạm bản quyền không? (vụ kiện Getty Images vs Stability AI, The New York Times vs OpenAI); (2) Sản phẩm AI — ai là tác giả của nội dung AI tạo ra?; (3) Trách nhiệm — ai chịu trách nhiệm khi AI tạo nội dung sai lệch hoặc có hại? Phân tích luật pháp Mỹ, EU và Việt Nam.',
'/uploads/ip_generative_ai.pdf','2026-05-06 15:00:00',28,'completed',78,NULL,'2026-05-06 15:01:18'),
 
-- === Cao Thị Trang (id=34) — Tâm lý học, thần kinh học ===
(77,34,'Mindfulness-Based Cognitive Therapy: Efficacy for Depression Relapse Prevention',
'Liệu pháp nhận thức dựa trên chánh niệm (MBCT) kết hợp thiền chánh niệm với các kỹ thuật CBT để ngăn ngừa tái phát trầm cảm. Meta-analysis này tổng hợp 33 RCT với 2.748 bệnh nhân trầm cảm tái phát từ năm nghiên cứu của Kuyken, Teasdale và cộng sự. Kết quả: MBCT giảm nguy cơ tái phát 43% so với nhóm chăm sóc thông thường (OR = 0,57); hiệu quả tương đương thuốc chống trầm cảm duy trì nhưng không có tác dụng phụ. Hiệu quả nhất với bệnh nhân từng trải qua ≥3 đợt trầm cảm.',
'/uploads/mbct_depression_meta_analysis.pdf','2026-04-29 09:00:00',20,'completed',56,NULL,'2026-04-29 09:00:56'),
 
(78,34,'The Neuroscience of Learning: Memory Consolidation, Sleep and Optimal Study Strategies',
'Thần kinh học về học tập đã tiết lộ các nguyên lý sinh học cơ bản của ghi nhớ và quên lãng. Bài báo này tổng hợp nghiên cứu về: (1) Củng cố ký ức — hippocampus mã hóa ký ức ngắn hạn, vỏ não lưu trữ dài hạn qua quá trình diễn ra chủ yếu trong giấc ngủ; (2) Đường cong quên lãng Ebbinghaus và lịch trình nhắc lại tối ưu (spaced repetition); (3) Kỹ thuật học hiệu quả: retrieval practice > re-reading (effect size d=0.5-1.0), interleaving > blocking, và elaborative interrogation. Ứng dụng cho thiết kế chương trình học và hệ thống học tập thích nghi.',
'/uploads/neuroscience_learning.pdf','2026-05-08 08:30:00',24,'completed',67,NULL,'2026-05-08 08:31:07'),
 
-- === Vũ Đình Long (id=35) — Y học, dược học ===
(79,35,'Immunotherapy for Solid Tumors: Current State and Future Directions',
'Liệu pháp miễn dịch ung thư đã cách mạng hóa điều trị với tỷ lệ đáp ứng lâu dài chưa từng có. Bài tổng quan này đánh giá hiệu quả của các loại liệu pháp miễn dịch: checkpoint inhibitors (anti-PD-1/PD-L1, anti-CTLA-4), CAR-T cells, tumor-infiltrating lymphocytes (TIL) và cancer vaccines cá nhân hóa (neoantigen-based). Thách thức với khối u đặc (solid tumors): rào cản vật lý vi môi trường khối u, miễn dịch ức chế và thoát miễn dịch. Chiến lược kết hợp: checkpoint inhibitor + hóa trị, CAR-T thế hệ 4 và bispecific antibody.',
'/uploads/immunotherapy_solid_tumors.pdf','2026-05-01 11:00:00',35,'completed',97,NULL,'2026-05-01 11:01:37'),
 
(80,35,'Drug Repurposing: Computational Methods and Clinical Opportunities',
'Tái định vị thuốc (Drug Repurposing) tìm kiếm công dụng mới cho thuốc đã được phê duyệt — tiết kiệm 40-60% chi phí và thời gian phát triển so với thuốc mới. Bài báo này trình bày các phương pháp tính toán hiện đại: network medicine (phân tích mạng tương tác protein-protein), molecular docking ảo, machine learning trên dữ liệu omics và large language models phân tích y văn. Thành công điển hình: sildenafil (từ cao huyết áp → rối loạn cương dương), metformin (tiểu đường → tiềm năng chống lão hóa và ung thư). Phân tích pipeline COVID-19 drug repurposing với 200+ ứng viên.',
'/uploads/drug_repurposing_computational.pdf','2026-05-10 09:00:00',30,'uploaded',NULL,NULL,'2026-05-10 09:00:00');
