INSERT INTO `summaries` VALUES
(1,1,'short','Bài báo giới thiệu kiến trúc Transformer — mô hình dịch máy hoàn toàn dựa trên cơ chế attention, không dùng RNN hay CNN. Đạt 28,4 BLEU trên WMT 2014 En-De, vượt trội về chất lượng và tốc độ huấn luyện.','2026-04-10 08:15:38'),
(2,1,'detailed','Bài báo "Attention Is All You Need" (Vaswani et al., 2017) đề xuất kiến trúc Transformer, một bước ngoặt trong NLP. Kiến trúc bao gồm encoder-decoder với multi-head self-attention và feed-forward layers. Điểm mạnh chính là khả năng song song hóa hoàn toàn — khác với RNN phải xử lý tuần tự. Cơ chế scaled dot-product attention tính toán trọng số chú ý bằng Q·Kᵀ/√d_k, sau đó softmax và nhân với V. Multi-head attention chạy h phép attention song song trên các không gian con khác nhau. Positional encoding bù đắp cho việc không có thông tin thứ tự từ. Kết quả: BLEU 28,4 (En-De) và 41,0 (En-Fr), với thời gian huấn luyện chỉ 12 giờ trên 8 GPU P100. Kiến trúc này là nền tảng của BERT, GPT và hầu hết các mô hình NLP hiện đại.','2026-04-10 08:15:38'),
(3,2,'short','BERT tiền huấn luyện các biểu diễn ngôn ngữ hai chiều sâu bằng cách che một số token ngẫu nhiên và dự đoán chúng (Masked LM). Sau khi fine-tune, BERT đạt SOTA trên 11 tác vụ NLP bao gồm GLUE, SQuAD và SWAG.','2026-04-11 09:30:55'),
(4,2,'detailed','BERT (Bidirectional Encoder Representations from Transformers) của Devlin et al. (2018) là mô hình tiền huấn luyện ngôn ngữ mang tính đột phá. Khác với GPT (chỉ nhìn trái sang phải), BERT dùng kiến trúc Transformer encoder hai chiều. Hai mục tiêu tiền huấn luyện: (1) Masked Language Model (MLM) — che 15% token ngẫu nhiên và dự đoán chúng, giúp học ngữ cảnh hai chiều; (2) Next Sentence Prediction (NSP) — dự đoán liệu câu B có đứng sau câu A không. BERT-Base có 12 lớp, 768 hidden units, 12 attention heads (110M tham số); BERT-Large có 24 lớp, 1024 hidden units (340M tham số). Fine-tuning trên các tác vụ downstream bằng cách thêm lớp classification đơn giản. Kết quả: cải thiện GLUE từ 80,5 lên 82,1; SQuAD 1.1 F1 từ 91,7 lên 93,2. BERT đặt nền móng cho RoBERTa, DistilBERT, ALBERT và phần lớn mô hình NLP hiện đại.','2026-04-11 09:30:55'),
(5,3,'short','ResNet giải quyết vấn đề degradation trong mạng rất sâu bằng kết nối tắt (skip connections), cho phép gradient đi qua nhiều lớp mà không bị mất. Mạng 152 lớp đạt top-5 error 3,57% trên ImageNet, giành chiến thắng ILSVRC 2015.','2026-04-12 14:00:47'),
(6,3,'detailed','Deep Residual Learning (He et al., 2015) giải quyết vấn đề degradation — mạng sâu hơn có độ chính xác huấn luyện cao hơn không được đảm bảo. Ý tưởng cốt lõi: thay vì học ánh xạ H(x), các lớp học phần dư F(x) = H(x) - x, khi đó H(x) = F(x) + x. Skip connections thực hiện phép cộng giống hệt (identity shortcut). Điều này tạo điều kiện cho gradient chảy trực tiếp qua nhiều lớp, giải quyết vanishing gradient. Kiến trúc bottleneck dùng conv 1×1 để giảm/tăng chiều, giúp xây dựng mạng sâu hơn với ít tham số. Các biến thể ResNet-18, 34, 50, 101, 152 cho phép lựa chọn theo tài nguyên. Trên ImageNet: top-5 error 3,57% (ResNet-152), vượt qua con người (5,1%). Ảnh hưởng: ResNet đã được trích dẫn hơn 100.000 lần và là backbone phổ biến nhất cho computer vision.','2026-04-12 14:00:47'),
(7,4,'short','GAN giới thiệu framework đối kháng: generator tạo ảnh giả, discriminator phân biệt thật/giả. Cả hai cùng huấn luyện theo kiểu minimax. Kết quả: có thể tạo ảnh thực tế đến mức không thể phân biệt, mở ra lĩnh vực generative modeling.','2026-04-13 10:00:29'),
(8,5,'short','GPT-4 là mô hình đa phương thức có thể xử lý văn bản và hình ảnh. Đạt điểm top 10% trong kỳ thi luật sư mô phỏng; vượt GPT-3.5 đáng kể trên hầu hết các bài kiểm tra chuẩn. Báo cáo kỹ thuật mô tả phương pháp huấn luyện và đánh giá an toàn.','2026-04-14 11:33:00'),
(9,5,'detailed','GPT-4 Technical Report (OpenAI, 2023) mô tả mô hình ngôn ngữ lớn đa phương thức mạnh nhất hiện tại của OpenAI. Đặc điểm chính: (1) Đa phương thức — nhận đầu vào hình ảnh và văn bản; (2) Context window 32K token; (3) Hiệu suất vượt trội: MMLU 86,4% (so với GPT-3.5 70%), HumanEval coding 67% và nhiều bài kiểm tra chuyên nghiệp. GPT-4 vượt qua kỳ thi GRE Verbal (99th percentile), luật sư mô phỏng (90th percentile), và nhiều bài kiểm tra y khoa. Phương pháp RLHF được cải tiến và Constitutional AI giúp mô hình an toàn hơn so với GPT-3.5. Báo cáo thừa nhận các hạn chế: vẫn có hallucination, thiếu thông tin sau cut-off date và thiên kiến. Đây là mô hình thương mại chủ lực của OpenAI, được tích hợp trong ChatGPT Plus và API.','2026-04-14 11:33:00'),
(10,6,'short','Bài khảo sát toàn diện về LLMs bao gồm lịch sử phát triển, kiến trúc Transformer, kỹ thuật tiền huấn luyện, instruction tuning, RLHF và alignment. Cung cấp tổng quan tốt cho người muốn hiểu nền tảng kỹ thuật của các mô hình như GPT, PaLM và LLaMA.','2026-04-15 09:01:15'),
(11,7,'short','RAG kết hợp truy xuất tài liệu với mô hình sinh ngôn ngữ để trả lời câu hỏi cần kiến thức. Mô hình truy xuất tài liệu liên quan từ Wikipedia, sau đó generator tổng hợp thành câu trả lời. Đạt SOTA trên NaturalQuestions, TriviaQA và WebQuestions.','2026-04-16 10:00:42'),
(12,7,'detailed','Retrieval-Augmented Generation (Lewis et al., 2020) giải quyết vấn đề factual knowledge trong mô hình seq2seq. Kiến trúc gồm hai phần: (1) Retriever — DPR (Dense Passage Retrieval) mã hóa query và document thành vector, tìm k tài liệu gần nhất trong không gian embedding; (2) Generator — BART tạo câu trả lời dựa trên query + tài liệu truy xuất. Hai biến thể: RAG-Sequence (dùng cùng tài liệu cho toàn bộ output) và RAG-Token (tài liệu khác nhau cho từng token). Ưu điểm so với mô hình chỉ dùng bộ nhớ tham số: có thể cập nhật kiến thức mà không cần retrain, cung cấp nguồn trích dẫn có thể kiểm chứng. RAG hiện là foundation của hầu hết hệ thống QA và chatbot doanh nghiệp.','2026-04-16 10:00:42'),
(13,8,'short','Constitutional AI của Anthropic dạy mô hình tự đánh giá và sửa đổi phản hồi dựa trên tập nguyên tắc đạo đức. Phương pháp RLAIF thay thế một phần RLHF để giảm phụ thuộc vào nhãn của con người. Claude được huấn luyện theo phương pháp này.','2026-04-17 13:00:53'),
(14,9,'short','LLaMA là họ mô hình ngôn ngữ mở với 7B-65B tham số, được huấn luyện hoàn toàn trên dữ liệu công khai. LLaMA-13B đánh bại GPT-3 (175B) trên nhiều benchmark. Mở ra xu hướng mô hình nguồn mở mạnh mẽ.','2026-04-18 08:31:06'),
(15,10,'short','Nghiên cứu cho thấy hiệu suất mô hình ngôn ngữ cải thiện theo quy luật lũy thừa với số tham số, kích thước dataset và lượng tính toán. Các quy luật này giúp dự báo hiệu suất và tối ưu phân bổ ngân sách compute.','2026-04-19 11:02:35'),
(16,10,'detailed','Scaling Laws (Kaplan et al., 2020) là nghiên cứu thực nghiệm quan trọng của OpenAI về cách hiệu suất mô hình ngôn ngữ thay đổi theo quy mô. Phát hiện chính: Hiệu suất (đo bằng cross-entropy loss) tuân theo quy luật lũy thừa với: N (số tham số): L ∝ N^(-0.076); D (kích thước dataset): L ∝ D^(-0.095); C (compute FLOPs): L ∝ C^(-0.050). Hàm ý thực tế: để tối ưu với ngân sách compute cố định, cần cân bằng giữa model size và số training tokens. Kaplan et al. đề xuất tăng cả N và D đồng thời. Nghiên cứu Chinchilla sau này (Hoffmann et al., 2022) cải chính: với compute budget cố định, nên dùng mô hình nhỏ hơn nhưng train trên nhiều data hơn. Ứng dụng: căn cứ để thiết kế GPT-3, PaLM, Gopher và nhiều mô hình khác.','2026-04-19 11:02:35'),
(17,11,'short','AlphaFold của DeepMind dùng deep learning để dự đoán cấu trúc 3D protein từ chuỗi amino acid với độ chính xác nguyên tử. Giải quyết bài toán tồn tại 50 năm trong sinh học cấu trúc. Đạt GDT_TS ~92,4 trên CASP14, vượt tất cả phương pháp khác.','2026-04-20 09:00:35'),
(18,12,'short','Nghiên cứu dùng CRISPR-Cas9 để thực hiện màn hình di truyền quy mô lớn trong tế bào ung thư người, xác định các gen liên quan đến kháng thuốc hóa trị. Phương pháp này cho phép xác định các mục tiêu điều trị tiềm năng một cách hệ thống và nhanh chóng.','2026-04-21 10:00:24'),
(19,13,'short','Vaccine mRNA-1273 (Moderna) đạt hiệu quả 94,1% trong thử nghiệm pha 3 với 30.420 người tham gia. Hiệu quả bảo vệ chống COVID-19 nặng là 100%. Tác dụng phụ chủ yếu ở mức độ nhẹ đến vừa và tạm thời. Đây là bằng chứng quan trọng hỗ trợ phê duyệt khẩn cấp.','2026-04-22 14:00:45'),
(20,13,'detailed','Thử nghiệm pha 3 mRNA-1273 (Baden et al., NEJM 2021) là một trong những nghiên cứu lâm sàng quan trọng nhất trong lịch sử y học hiện đại. Thiết kế: RCT đa trung tâm, 30.420 người (15.210 nhận vaccine, 15.210 nhận giả dược), tiêm hai mũi cách nhau 28 ngày. Kết quả sơ bộ: 196 ca COVID-19 có triệu chứng — 185 ca trong nhóm giả dược, 11 ca trong nhóm vaccine, hiệu quả 94,1%. Tất cả 30 ca COVID-19 nặng đều ở nhóm giả dược (hiệu quả 100%). Tính an toàn: tác dụng phụ chủ yếu cục bộ (đau tại vị trí tiêm 88,6% sau mũi 2) và toàn thân (mệt mỏi 68,5%, đau đầu 63,0%), thường tự hết sau 2-3 ngày. Không có sự kiện bất lợi nghiêm trọng liên quan đến vaccine. Đây là cơ sở cho phê duyệt sử dụng khẩn cấp từ FDA tháng 12/2020.','2026-04-22 14:00:45'),
(21,14,'short','Dự án Microbiome Con người (HMP) lập bản đồ vi sinh vật tại 15-18 vị trí cơ thể của 242 người khỏe mạnh. Xác định hơn 10.000 loài vi sinh vật; phát hiện mỗi cá nhân có "chữ ký microbiome" độc đáo trong khi chia sẻ một tập gen vi sinh vật cốt lõi.','2026-04-23 09:00:54'),
(22,15,'short','Bài tổng quan mô tả các cơ chế phân tử của SARS-CoV-2: protein Spike gắn ACE2 qua RBD, priming bởi TMPRSS2, nhân bản RNA qua RdRp. Bão cytokine và viêm phổi nặng do phản ứng miễn dịch quá mức. Đây là cơ sở để phát triển thuốc đặc hiệu như thuốc ức chế protease và kháng thể trung hòa.','2026-04-24 11:31:00'),
(23,16,'short','Bitcoin whitepaper (Nakamoto, 2008) đề xuất hệ thống tiền điện tử ngang hàng dùng blockchain — chuỗi block có hash liên kết — để ngăn chi tiêu đôi mà không cần bên thứ ba. Đây là nền tảng của toàn bộ hệ sinh thái tiền điện tử và Web3.','2026-04-25 08:00:22'),
(24,17,'short','Ethereum mở rộng blockchain Bitcoin với ngôn ngữ lập trình Turing-complete (Solidity), cho phép tạo hợp đồng thông minh tự thực thi. Tạo nền tảng cho DeFi, NFT và Web3. Chuyển từ PoW sang PoS trong "The Merge" năm 2022 giảm 99,95% năng lượng tiêu thụ.','2026-04-26 09:31:28'),
(25,19,'short','Nghiên cứu khảo sát 500+ tổ chức về DevOps cho thấy các tổ chức high-performing triển khai code nhanh hơn 200 lần, phục hồi sự cố nhanh hơn 24 lần. Các thực hành then chốt: CI/CD, version control, monitoring toàn diện và văn hóa học hỏi.','2026-04-28 11:00:55'),
(26,20,'short','Bài khảo sát điện toán đám mây trình bày kiến trúc 3-tier (IaaS/PaaS/SaaS), mô hình triển khai public/private/hybrid và các thách thức chính: bảo mật dữ liệu, vendor lock-in, độ trễ và quản lý chi phí. Khuyến nghị chiến lược multi-cloud.','2026-04-29 09:01:12'),
(27,21,'short','Phân tích so sánh Hadoop MapReduce và Apache Spark cho thấy Spark nhanh hơn 100x với xử lý in-memory. Đề xuất kiến trúc Lambda Architecture kết hợp batch và streaming. Ứng dụng thực tế trong phát hiện gian lận, chẩn đoán y tế và giao thông thông minh.','2026-04-30 08:31:03'),
(28,21,'detailed','Big Data Analytics (Gandomi & Haider, 2015 + cập nhật) tổng hợp phương pháp xử lý và phân tích dữ liệu lớn. Đặc điểm 5V: Volume (petabyte+), Velocity (real-time), Variety (structured/unstructured), Veracity (chất lượng) và Value (giá trị kinh doanh). Kiến trúc Lambda: (1) Batch layer — Hadoop MapReduce/Spark tính toán batch view trên toàn bộ dữ liệu lịch sử; (2) Speed layer — Apache Flink/Kafka Streams xử lý dữ liệu thời gian thực; (3) Serving layer — Cassandra/HBase phục vụ query. Các thuật toán ML trên quy mô lớn: Spark MLlib hỗ trợ linear regression, decision trees, random forests phân tán. Ứng dụng y tế: phân tích hồ sơ bệnh nhân để dự đoán nguy cơ; tài chính: phát hiện gian lận real-time; giao thông: tối ưu lộ trình và dự báo ùn tắc. Thách thức: GDPR và quyền riêng tư, chi phí lưu trữ và xử lý, thiếu nhân lực data science.','2026-04-30 08:31:03'),
(29,22,'short','Hướng dẫn toàn diện về học máy giới thiệu 6 thuật toán cốt lõi: linear regression, logistic regression, SVM, decision tree, k-means clustering và neural network. Mỗi thuật toán có ví dụ thực tế, ưu/nhược điểm và guidelines lựa chọn theo bài toán.','2026-05-01 09:01:20'),
(30,24,'short','Khảo sát so sánh các thuật toán object detection từ R-CNN (2013) đến YOLO v8 (2023). YOLO đạt cân bằng tốt nhất giữa tốc độ (500+ FPS) và độ chính xác (56,8 mAP trên COCO). Transformer-based detector (DETR) có tiềm năng nhưng cần nhiều dữ liệu và compute hơn.','2026-05-03 14:01:27'),
(31,24,'detailed','Object Detection Survey phân tích sự phát triển của bài toán phát hiện đối tượng theo thời gian. Giai đoạn 1 (trước 2012): HOG + SVM (Dalal & Triggs, 2005) dùng Histogram of Oriented Gradients, đạt ~70% precision trên pedestrian detection. Giai đoạn 2 (2013-2016): R-CNN family — R-CNN trích xuất 2000 region proposals qua Selective Search, classify bằng SVM; Fast R-CNN cải thiện với RoI pooling; Faster R-CNN thêm Region Proposal Network cho end-to-end training, 5 FPS. Giai đoạn 3 (2016-nay): YOLO (You Only Look Once) — chia ảnh thành lưới, dự đoán box + class trực tiếp trong một lần forward pass; YOLOv8 (2023) đạt 52,9 mAP@0.5 COCO, 160 FPS. SSD cân bằng speed-accuracy tốt. Giai đoạn 4 (2020-nay): DETR dùng Transformer encoder-decoder, loại bỏ NMS; GroundingDINO cho open-vocabulary detection. Tiêu chí đánh giá: mAP (mean Average Precision) tại IoU threshold 0.5 và 0.5:0.95.','2026-05-03 14:01:27'),
(32,26,'short','Báo cáo IPCC 2022 kết luận tác động khí hậu đã vượt quá khả năng thích nghi tự nhiên ở nhiều khu vực. Ngay với 1,5°C ấm lên, 1 tỷ người đối mặt nguy cơ nắng nóng cực đoan; ở 4°C, 3,3-3,6 tỷ người trong vùng nguy hiểm cao. Cần hành động khẩn cấp cả về giảm phát thải lẫn thích nghi.','2026-05-05 10:02:45'),
(33,26,'detailed','IPCC AR6 Working Group II (2022) đánh giá tác động, rủi ro và khả năng thích nghi với biến đổi khí hậu. Phát hiện chính: (1) Tác động đã xảy ra: đã xác nhận tác động do biến đổi khí hậu tại 127 quốc gia, mất đa dạng sinh học, suy giảm sản lượng nông nghiệp và y tế. (2) Rủi ro theo kịch bản: 1,5°C — 14% loài mất sinh cảnh nghiêm trọng; 2°C — san hô nhiệt đới giảm 99%; 4°C — thiệt hại kinh tế toàn cầu 10-23% GDP. (3) Điểm tới hạn: sụp đổ tảng băng Greenland và Tây Nam Cực, phá rừng Amazon, tan băng vĩnh cửu Bắc Cực. (4) Công bằng khí hậu: các quốc gia phát thải ít nhất chịu rủi ro lớn nhất. Giải pháp thích nghi ưu tiên: hạ tầng chịu khí hậu, bảo vệ hệ sinh thái ven biển, hệ thống cảnh báo sớm và chuyển đổi nông nghiệp bền vững.','2026-05-05 10:02:45'),
(34,27,'short','Phân tích chi phí năng lượng tái tạo 2010-2020: solar PV giảm 89%, điện gió ngoài khơi giảm 70%. LCOE (Levelized Cost of Energy) của solar hiện là 0,033 USD/kWh, thấp hơn than và khí đốt. Dự báo năng lượng tái tạo chiếm 90% tăng trưởng công suất điện toàn cầu đến 2025.','2026-05-06 09:00:40'),
(35,28,'short','Phân tích tác động của EV đến lưới điện: 100 triệu xe EV đến 2030 tăng nhu cầu điện 8-15%. Sạc thông minh và V2G (Vehicle-to-Grid) có thể chuyển gánh nặng từ giờ cao điểm sang thấp điểm, tiết kiệm chi phí hạ tầng 10-40 tỷ USD. Yêu cầu đầu tư lưới điện thông minh 500 tỷ USD đến 2040.','2026-05-07 11:00:58'),
(36,29,'short','Kinh tế tuần hoàn có thể giảm 45% phát thải toàn cầu đến 2030. Renault tái sản xuất động cơ tiết kiệm 80% năng lượng so với sản xuất mới; Philips chuyển sang mô hình "ánh sáng như dịch vụ" giảm thiểu chất thải. Rào cản chính: tư duy tuyến tính, thiếu tiêu chuẩn và chi phí chuyển đổi ban đầu.','2026-05-08 09:01:05'),
(37,31,'short','Phân tích nguyên tắc đầu tư giá trị: tìm cổ phiếu có margin of safety (mua thấp hơn giá trị nội tại ít nhất 25%). Phương pháp DCF định giá dòng tiền tương lai; P/E thấp không đồng nghĩa với cổ phiếu rẻ. Buffett bổ sung: ưu tiên doanh nghiệp chất lượng cao với lợi thế cạnh tranh bền vững.','2026-05-01 10:01:29'),
(38,32,'short','Phân tích rủi ro DeFi năm 2023: smart contract bugs gây thiệt hại 3,8 tỷ USD; oracle manipulation và flash loan attacks chiếm 40% vụ hack. Uniswap V3 tập trung thanh khoản tăng hiệu quả vốn 4000x so với V2. Quy định pháp lý DeFi đang được hình thành tại EU và Mỹ.','2026-05-02 09:01:19'),
(39,33,'short','Lý thuyết triển vọng (Kahneman-Tversky) chứng minh con người: định giá lỗ mạnh hơn lời (loss aversion 2:1), đánh giá xác suất không tuyến tính, ra quyết định theo khung tham chiếu. Các ứng dụng: thiết kế chương trình tiết kiệm hưu trí, giảm thiểu bias trong đầu tư, cải thiện chính sách y tế công cộng.','2026-05-03 11:00:51'),
(40,34,'short','Tổng quan ung thư học phân tử: 6 đặc điểm ung thư (Hanahan-Weinberg) bao gồm tự đủ tín hiệu tăng trưởng, kháng apoptosis, không giới hạn sao chép, xâm lấn mô và di căn, tạo mạch và né tránh miễn dịch. Liệu pháp nhắm mục tiêu (imatinib, trastuzumab) và checkpoint inhibitor (nivolumab, pembrolizumab) cách mạng hóa điều trị.','2026-04-20 08:01:38'),
(41,34,'detailed','Molecular Biology of Cancer (tổng hợp từ Hanahan & Weinberg 2011 + cập nhật 2022) mô tả nền tảng phân tử của ung thư. Hai đặc điểm mới bổ sung: tái lập trình chuyển hóa (Warburg effect — tế bào ung thư ưa glycolysis kể cả khi có oxy) và né tránh tiêu hủy miễn dịch. Các đột biến driver phổ biến: TP53 (gần 50% ung thư), KRAS (25%), PIK3CA (15%). Con đường tín hiệu: PI3K/AKT/mTOR, RAS/RAF/MEK/ERK, Wnt/β-catenin và p53. Liệu pháp nhắm mục tiêu: imatinib (Gleevec) cho CML ức chế BCR-ABL fusion protein, thay đổi tỷ lệ sống sót 5 năm từ 30% lên 89%; trastuzumab (Herceptin) cho ung thư vú HER2+. Liệu pháp miễn dịch: PD-1/PD-L1 checkpoint inhibitors (nivolumab, pembrolizumab) hoạt động tốt với tumor mutational burden cao. CAR-T cells cho ung thư máu đạt remission >80% với ALL tái phát. Thách thức: kháng thuốc do heterogeneity khối u và áp lực tiến hóa.','2026-04-20 08:01:38'),
(42,35,'short','Nghiên cứu trục ruột-não phát hiện vi sinh vật đường ruột sản xuất 90% serotonin cơ thể và ảnh hưởng đến trục HPA (stress). Rối loạn dysbiosis liên quan đến trầm cảm, lo lắng và Parkinson. Bổ sung probiotics (Lactobacillus, Bifidobacterium) cho kết quả tích cực trong 8/10 thử nghiệm lâm sàng nhỏ.','2026-04-21 09:30:58'),
(43,37,'short','Phân tích sự trỗi dậy của Rome: quân đoàn La Mã (legionary system) với huấn luyện chuyên nghiệp và kỷ luật sắt thắng 3 cuộc Chiến tranh Punic (264-146 TCN). Hệ thống municipia — trao quyền công dân La Mã cho đồng minh — tạo trung thành và nguồn nhân lực vô tận. Chuyển từ Cộng hòa sang Đế chế do mâu thuẫn giai cấp và sức mạnh quân sự cá nhân (Caesar, Augustus).','2026-04-25 09:01:52'),
(44,38,'short','Cách mạng Công nghiệp Anh (1760-1840): máy hơi nước của Watt + ngành dệt cơ giới hóa + đường sắt là 3 đòn bẩy chính. Năng suất lao động tăng 20 lần; dân số đô thị từ 20% lên 54% năm 1851. Hệ quả: tầng lớp trung lưu nổi lên, phong trào lao động Chartist và Marx viết Tư Bản Luận. Mô hình lan rộng sang Pháp, Đức, Mỹ sau 1840.','2026-04-26 10:31:23'),
(45,39,'short','Chiến tranh Lạnh: Học thuyết Truman (1947) ngăn chặn chủ nghĩa cộng sản; Kế hoạch Marshall (1948) tái thiết Tây Âu. Khủng hoảng tên lửa Cuba (1962) là đỉnh điểm nguy hiểm nhất. Détente (1970s) tạm thời giảm căng thẳng. Gorbachev với glasnost và perestroika dẫn đến sụp đổ Liên Xô 1991, kết thúc trật tự thế giới lưỡng cực.','2026-04-27 08:01:37'),
(46,40,'short','Chủ nghĩa Khắc kỷ: phân biệt "điều trong tầm kiểm soát" (suy nghĩ, hành động) vs "điều ngoài tầm kiểm soát" (danh tiếng, kết quả). Thực hành: memento mori, negative visualization và amor fati. Ứng dụng hiện đại trong CBT (Cognitive Behavioral Therapy), stoic journaling và quản lý cảm xúc. Ryan Holiday và Tim Ferriss phổ biến hóa cho thế hệ millennial.','2026-04-28 11:01:00'),
(47,41,'short','Khảo sát 1.200 giáo viên và 3.500 học sinh về học trực tuyến hậu COVID: 67% học sinh thích mô hình blended (kết hợp online/offline); MOOC tỷ lệ hoàn thành chỉ 5-15% (vấn đề motivation). AI tutoring cá nhân hóa lộ trình học tập tăng kết quả 20-30%. Khoảng cách số giữa đô thị và nông thôn là thách thức lớn nhất.','2026-05-01 08:01:08'),
(48,42,'short','6 bias nhận thức quan trọng nhất: confirmation bias (tìm bằng chứng phù hợp định kiến), anchoring (ảnh hưởng quá lớn của thông tin đầu tiên), availability heuristic (đánh giá xác suất qua ví dụ dễ nhớ), sunk cost fallacy, overconfidence bias và dunning-kruger effect. Các kỹ thuật giảm bias: pre-mortem analysis, devil\'s advocate, structured decision frameworks.','2026-05-02 09:30:57'),
(49,43,'short','GenAI năm 2023-2024: GPT-4V, Gemini Ultra, Claude 3 Opus đạt trên mức con người trong nhiều bài kiểm tra chuẩn. Ứng dụng: coding assistant (GitHub Copilot tiết kiệm 55% thời gian), phân tích tài liệu y tế, tạo nội dung marketing. Rủi ro: 44% nhân viên lo ngại mất việc làm; hallucination vẫn là thách thức kỹ thuật chính. Khuyến nghị: triển khai có kiểm soát với human-in-the-loop.','2026-05-03 10:01:19'),
(50,44,'short','Lịch sử NLP: từ rule-based parser (1950s) đến statistical (1990s: n-gram, HMM), ML (2000s: SVM, MaxEnt), deep learning (2013: word2vec, 2014: LSTM) và Transformer (2017). BERT (2018) và GPT-3 (2020) đánh dấu kỷ nguyên pre-training + fine-tuning. Hiện tại: instruction-following LLMs có thể giải quyết hầu hết tác vụ NLP zero-shot.','2026-05-04 09:01:13'),
(51,45,'short','Blockchain: immutable ledger với Merkle tree + consensus (PoW tốn năng lượng, PoS hiệu quả hơn 99%). Smart contract trên Ethereum tự thực thi khi điều kiện thỏa mãn. Ứng dụng supply chain: Walmart dùng blockchain giảm thời gian truy xuất nguồn gốc thực phẩm từ 7 ngày xuống 2,2 giây.','2026-05-05 10:01:24'),
(52,47,'short','Quy trình phát triển vaccine: discovery → tiền lâm sàng → pha I (an toàn, n~20-100) → pha II (immunogenicity, n~100-1000) → pha III (hiệu quả, n>10.000) → EUA/phê duyệt. mRNA vaccine hoàn thiện trong <1 năm nhờ: thiết kế sequence nhanh, không cần nuôi cấy virus sống, khả năng sản xuất quy mô lớn. Nền tảng mRNA tiếp tục phát triển cho HIV, ung thư và cúm.','2026-05-03 09:00:56'),
(53,48,'short','Mực nước biển tăng trung bình 3,6 mm/năm (2006-2015), nhanh gấp đôi so với thế kỷ 20. Nguyên nhân: giãn nở nhiệt (42%) và tan băng sông băng/tảng băng (58%). Dự báo tăng 0,43-0,84 m đến 2100 theo kịch bản trung bình; 300 triệu người sống dưới mực nước lũ 100 năm sẽ bị ảnh hưởng mỗi năm.','2026-05-04 10:00:50'),
(54,49,'short','Máy tính lượng tử: qubit có thể tồn tại ở trạng thái superposition, tăng không gian tính toán theo hàm mũ. Thuật toán Shor phá mã RSA trong thời gian đa thức — đe dọa mật mã hiện tại. Thuật toán Grover tìm kiếm cơ sở dữ liệu N phần tử trong O(√N). Thách thức: decoherence, error rate ~0,1-1%, cần ~1 triệu qubit vật lý cho 1 qubit logic lỗi có thể chỉnh.','2026-05-05 08:01:34'),
(55,50,'short','Mối đe dọa AI trong an ninh mạng: deepfake audio/video lừa đảo tăng 3000% năm 2023; adversarial examples đánh lừa nhận dạng ảnh với thay đổi pixel vô hình. Phòng thủ AI: anomaly detection bằng autoencoder phát hiện bất thường, UEBA (User and Entity Behavior Analytics) giảm false positive 60%. Khuyến nghị: zero trust + AI-assisted SOC.','2026-05-06 10:01:10'),
(56,51,'short','Doanh nghiệp áp dụng AI sớm đạt tăng năng suất 15-22% trong 3 năm, nhưng tác động phân phối không đồng đều — lao động kỹ năng cao hưởng lợi nhiều hơn. Khuyến nghị chính sách: đào tạo lại lực lượng lao động, điều chỉnh hệ thống thuế và tăng đầu tư công vào nghiên cứu AI cơ bản.','2026-04-11 09:16:17'),
(57,51,'detailed','Nghiên cứu của Brynjolfsson, Rock và Syverson (2023 — cập nhật bộ dữ liệu gốc 2019) lý giải nghịch lý Solow ("máy tính ở khắp nơi trừ trong số liệu năng suất"). Nguyên nhân trễ: AI cần đầu tư bổ sung vào vốn vô hình (quy trình, kỹ năng, dữ liệu) trước khi tạo ra năng suất — "J-curve" 3-5 năm. Phân tích 800 doanh nghiệp: tác động AI trên năng suất = +15% trung bình nhưng variance rất lớn (top quartile +38%, bottom quartile -3%). Tác động phân phối: lao động kỹ năng cao (cognitive non-routine) tăng lương 8-12%; lao động kỹ năng trung bình (routine cognitive) bị thay thế nhiều nhất. Hàm ý chính sách: (1) Đầu tư công vào R&D AI cơ bản vì positive spillovers; (2) Chương trình đào tạo lại (reskilling) lao động trung niên; (3) Mở rộng safety net (trợ cấp thất nghiệp, healthcare universal) để hấp thụ gián đoạn; (4) Cân nhắc robot tax như đề xuất của Bill Gates — còn tranh luận.','2026-04-11 09:16:17'),
 
-- paper 52: ESG Investing
(58,52,'short','Meta-analysis 1.200 nghiên cứu ESG: 58% cho kết quả tương quan dương với lợi nhuận, không phải kết quả nhất quán như marketing ESG thường tuyên bố. Điểm ESG cao nhất quán với rủi ro thấp hơn (biến động, beta) và chi phí vốn thấp hơn. Yếu tố G (Governance) có predictive power mạnh nhất; yếu tố E và S phụ thuộc ngành và thước đo.','2026-04-18 14:01:03'),
 
-- paper 53: MT Quality Estimation
(59,53,'short','QE hiện đại dựa trên BERT (TransQuest, CometKiwi) đạt tương quan Pearson 0,74-0,82 với đánh giá con người trên WMT — vượt xa các phương pháp thống kê truyền thống. Tuy nhiên, QE vẫn kém 15-20% so với MT metrics sử dụng bản dịch tham chiếu (BLEU, chrF). Hướng tương lai: QE đa chiều (trôi chảy, trung thành, phong cách) và QE document-level.','2026-04-22 09:30:50'),
 
-- paper 54: Low-resource NMT Vietnamese
(60,54,'short','Back-translation với 5 triệu câu đơn ngữ tiếng Việt cải thiện BLEU 8,4 điểm cho cặp Vi-En. Transfer learning từ mBERT cải thiện thêm 3,7 điểm. Đây là kết quả tốt nhất hiện tại cho NMT tiếng Việt với dưới 500.000 câu song ngữ — mở ra hướng ứng dụng cho các ngôn ngữ dân tộc thiểu số Việt Nam.','2026-04-30 10:01:07'),
(61,54,'detailed','Nghiên cứu này giải quyết thách thức NMT cho cặp Việt-Anh (low-resource: ~200.000 câu song ngữ chất lượng từ IWSLT, OpenSubtitles) và Việt-Khmer (very low-resource: <50.000 câu). Baseline: Transformer-base (6L encoder, 6L decoder) đạt BLEU 28,4 Vi→En với toàn bộ dữ liệu có sẵn. Các kỹ thuật được đánh giá: (1) Back-translation (Sennrich et al.): generate bản dịch En→Vi từ corpus đơn ngữ 5M câu, lọc bằng QE — tăng BLEU +8,4; (2) mBERT encoder initialization: fine-tune mBERT-multilingual làm encoder khởi tạo — +3,7 BLEU; (3) Vocabulary sharing với SentencePiece BPE; (4) Data augmentation: word dropout và token masking — +1,2 BLEU. Kết hợp tất cả kỹ thuật: BLEU 41,7 Vi→En, vượt qua Google Translate (BLEU 40,2) trên test set IWSLT 2022. Với Việt-Khmer: transfer learning từ mô hình Vi-En + Khmer Wikipedia monolingual đạt BLEU 18,3 (baseline: 7,2).','2026-04-30 10:01:07'),
 
-- paper 55: Edge AI
(62,55,'short','Quantization INT8 giảm kích thước mô hình 4x và tốc độ suy luận 2-3x với mất mát độ chính xác <1% trên MobileNetV3. Knowledge distillation từ teacher ResNet-50 sang student MobileNetV2 đạt 90% accuracy của teacher với 1/10 compute. TensorFlow Lite và ONNX Runtime là hai runtime edge phổ biến nhất với hỗ trợ phần cứng rộng nhất.','2026-05-01 08:01:12'),
 
-- paper 57: Mental health Vietnamese youth
(63,57,'short','32,6% học sinh THCS-THPT Việt Nam có triệu chứng lo lắng vừa-nặng — tỷ lệ cao hơn mức trung bình ASEAN (27%). Yếu tố bảo vệ mạnh nhất: kết nối gia đình và bạn bè tích cực, hoạt động thể chất thường xuyên và kỹ năng giải quyết vấn đề. Bài báo kêu gọi tích hợp chuyên gia tâm lý học đường vào 100% trường THPT và đưa giáo dục sức khỏe tâm thần vào chương trình học.','2026-04-15 10:01:24'),
(64,57,'detailed','Nghiên cứu dịch tễ học sức khỏe tâm thần thanh thiếu niên Việt Nam quy mô lớn nhất từ trước đến nay. Phương pháp: phân tầng ngẫu nhiên 12.450 học sinh từ 124 trường tại 8 tỉnh/thành (Hà Nội, TP.HCM, Đà Nẵng, Cần Thơ, Thái Nguyên, Nghệ An, Bình Dương, Cà Mau). Công cụ: GAD-7 (lo lắng), PHQ-9 (trầm cảm), AUDIT (sử dụng rượu). Kết quả chi tiết: Lo lắng — nhẹ 18,4%, vừa 21,3%, nặng 11,3% (tổng 51%); Trầm cảm — nhẹ 15,2%, vừa 11,4%, nặng 8,4% (tổng 35%). Yếu tố nguy cơ (logistic regression): áp lực thi cử (OR=2,8), bắt nạt học đường (OR=2,4), TikTok/Instagram >4h/ngày (OR=1,9), gia đình mâu thuẫn cao (OR=2,1). Yếu tố bảo vệ: thể dục >3 buổi/tuần (OR=0,61), tự đánh giá năng lực tốt (OR=0,54), có người lớn đáng tin cậy ngoài gia đình (OR=0,67). Mô hình can thiệp đề xuất: Tier 1 — chương trình toàn trường phổ cập kỹ năng cảm xúc; Tier 2 — nhóm hỗ trợ nhỏ cho học sinh có dấu hiệu; Tier 3 — chuyển tuyến tâm lý lâm sàng.','2026-04-15 10:01:24'),
 
-- paper 58: Telemedicine rural Vietnam
(65,58,'short','Telemedicine tại 45 trạm y tế xã vùng sâu đạt tỷ lệ hài lòng 68% và độ chính xác chẩn đoán 82%. Hội chẩn tâm thần và da liễu từ xa hiệu quả cao nhất; cấp cứu và sản khoa cần cải thiện giao thức. Đề xuất: đầu tư internet vệ tinh cho vùng mù sóng và chương trình đào tạo y tế số bắt buộc cho cán bộ y tế cơ sở.','2026-04-28 13:31:10'),
 
-- paper 59: Federated Learning
(66,59,'short','FedAvg hội tụ chậm với Non-IID data (dữ liệu không đồng đều giữa các client). FedProx thêm proximal term giảm client drift; SCAFFOLD dùng control variates cho hội tụ đảm bảo. Differential Privacy với ε=8 đủ bảo vệ quyền riêng tư nhưng giảm accuracy ~3-5%. Federated learning thực tế nhất cho ứng dụng y tế đa bệnh viện và tài chính đa tổ chức.','2026-04-20 09:01:29'),
(67,59,'detailed','Federated Learning (McMahan et al., Google 2017) giải quyết thách thức học máy trên dữ liệu nhạy cảm mà không tập trung. Vấn đề Non-IID: trong thực tế, dữ liệu của mỗi client (bệnh viện, điện thoại) có phân phối khác nhau — FedAvg gốc không hội tụ tốt, giảm accuracy 10-20% so với centralized training. FedProx (Li et al., 2020): thêm regularization ||w - w_global||² vào mục tiêu local training, kiểm soát client drift, hội tụ ngay cả khi clients training khác số iterations. SCAFFOLD (Karimireddy et al., 2020): dùng control variates để ước tính và hiệu chỉnh client drift, đạt linear speedup với số clients. Bảo mật: (1) Gradient Inversion Attack (Zhu et al.) có thể tái tạo dữ liệu huấn luyện từ gradient — phòng thủ bằng gradient compression; (2) Model Poisoning: client độc hại gửi gradient sai — phòng thủ Byzantine-robust aggregation (Krum, FLTrust); (3) Differential Privacy (Abadi et al.): thêm Gaussian noise, DP-SGD đảm bảo (ε,δ)-DP. Ứng dụng: Gboard (Google) dùng FL cho next-word prediction, Apple dùng cho Siri, WeBank (Trung Quốc) cho credit scoring đa ngân hàng.','2026-04-20 09:01:29'),
 
-- paper 60: Post-quantum cryptography
(68,60,'short','CRYSTALS-Kyber (trao đổi khóa) và CRYSTALS-Dilithium (chữ ký) là các thuật toán PQC được NIST chuẩn hóa năm 2024, dựa trên bài toán Module-LWE (học với lỗi). So với RSA-2048: Kyber-768 có khóa nhỏ hơn 30% nhưng chữ ký lớn hơn 3x. "Harvest now, decrypt later" attack yêu cầu bắt đầu di chuyển ngay — dữ liệu mật được thu thập hôm nay có thể bị giải mã khi máy tính lượng tử đủ mạnh.','2026-05-02 10:01:18'),
 
-- paper 61: Adaptive Learning Systems
(69,61,'short','So sánh 5 ALS thương mại: Duolingo hiệu quả nhất cho học ngôn ngữ (hoàn thành 3x so với sách giáo khoa); ALEKS mạnh cho toán học (giảm thiếu hổng kiến thức 35%); Khan Academy phổ biến nhất nhưng ít cá nhân hóa nhất. Yếu tố thành công: feedback tức thì, adaptive difficulty và yếu tố gamification không quá mức.','2026-04-16 08:31:00'),
 
-- paper 62: PBL STEM meta-analysis
(70,62,'short','PBL trong STEM đặc biệt hiệu quả ở kỹ năng giải quyết vấn đề (d=0,62) và làm việc nhóm (d=0,55). Điều kiện thành công: dự án kết nối bối cảnh thực tế, scaffold có cấu trúc và đánh giá formatif thường xuyên. PBL kém hiệu quả khi thiếu scaffolding hoặc khi đánh giá chỉ dựa trên bài kiểm tra truyền thống.','2026-05-04 14:00:53'),
 
-- paper 63: AMR Warehouse
(71,63,'short','Hệ thống 50 AMR tại kho Amazon đạt throughput 3.200 items/giờ — cao hơn 240% so với thủ công, với ROI trong 18 tháng. SLAM hybrid LiDAR + IMU đạt định vị chính xác ±2cm. Thuật toán phối hợp đa robot MAPF (Multi-Agent Path Finding) giải quyết tắc nghẽn với 99,7% thành công trong 1ms.','2026-04-17 10:01:16'),
 
-- paper 64: Digital Twin Manufacturing
(72,64,'short','Digital Twin tại Siemens Amberg: mô phỏng FEM thời gian thực dự báo sự cố máy móc trước 72 giờ với độ chính xác 87%. Bảo trì dự báo giảm unplanned downtime từ 4,2% xuống 2,1%. Đồng bộ dữ liệu 10.000 cảm biến mỗi 100ms qua MQTT → Apache Kafka → InfluxDB time-series.','2026-04-24 11:01:05'),
(73,64,'detailed','Digital Twin cho smart manufacturing là kết hợp của 4 thành phần: (1) Physical layer — máy móc, dây chuyền với 10.000+ cảm biến đo nhiệt độ, rung động, dòng điện, torque; (2) Data layer — Siemens Industrial Edge thu thập → MQTT → Apache Kafka streaming → InfluxDB time-series database; (3) Model layer — mô hình vật lý (Finite Element Method mô phỏng ứng suất cơ khí, Computational Fluid Dynamics cho nhiệt), kết hợp AI (LSTM dự báo sự cố, isolation forest phát hiện bất thường); (4) Application layer — giao diện operator HMI, scheduling tối ưu và AR visualization cho kỹ thuật viên bảo trì. Kết quả Siemens Amberg (2022): First Pass Yield tăng từ 99,1% lên 99,8% (giảm 75% lỗi sản phẩm). Lead time giảm 30%. Bảo trì dự báo: LSTM 3-lớp với 120 features từ cảm biến → dự báo hỏng hóc trước 72 giờ, precision 89%, recall 83%. Tiết kiệm 4,2 triệu EUR/năm chi phí bảo trì và phế phẩm. ROI Digital Twin: 14 tháng.','2026-04-24 11:01:05'),
 
-- paper 65: scRNA-seq
(74,65,'short','10x Chromium là nền tảng scRNA-seq phổ biến nhất: 3.000-10.000 tế bào/mẫu, chi phí 1.500-3.000 USD, nhưng coverage thấp (~2.000 genes/tế bào). Smart-seq2 đo đầy đủ transcriptome (~8.000 genes) nhưng chỉ xử lý ~400 tế bào/lần. Phân tích chuẩn (Seurat): QC filtering → normalization → PCA → UMAP → Leiden clustering → marker gene identification. Human Cell Atlas dùng scRNA-seq để lập bản đồ >80 triệu tế bào người.','2026-04-19 09:01:45'),
 
-- paper 66: Epigenetics
(75,66,'short','Methyl hóa DNA tại promoter CpG islands là cơ chế im lặng gene ổn định nhất — thường duy trì qua nhiều thế hệ tế bào. Histone H3K27me3 (Polycomb) đánh dấu gen bị im lặng; H3K4me3 đánh dấu promoter hoạt động. Trong ung thư: siêu methyl hóa im lặng gen ức chế khối u (BRCA1, MLH1, CDKN2A) là sự kiện sớm và có thể phát hiện trong máu (liquid biopsy).','2026-05-06 13:01:21'),
 
-- paper 67: Precision Agriculture
(76,67,'short','Thử nghiệm 120 ha lúa tại Cần Thơ và Sóc Trăng: hệ thống cảm biến LoRaWAN + drone đa phổ phát hiện bệnh đạo ôn sớm hơn quan sát thủ công 7-10 ngày, giảm thiệt hại 18%. Mô hình dự báo năng suất từ ảnh Sentinel-2 đạt RMSE 0,42 tấn/ha. Tổng kết: tiết kiệm 30% nước, 25% phân bón, tăng 12% năng suất, ROI dương sau 2 vụ.','2026-04-26 08:01:08'),
(77,67,'detailed','Hệ thống Nông nghiệp Chính xác tại Đồng bằng sông Cửu Long — nghiên cứu hợp tác ĐHCT và Bộ NN&PTNT 2022-2024. Kiến trúc: (1) Cảm biến mặt đất — 240 node LoRaWAN đo độ ẩm đất (Decagon 5TM), pH, EC, nhiệt độ, truyền về gateway 15 phút/lần; (2) Drone đa phổ — DJI P4 Multispectral với 5 kênh (RGB, Red Edge, NIR) bay lập bản đồ 2 lần/tháng; chỉ số NDVI phát hiện thiếu N, NDRE thiếu Fe, CWSI stress nước; (3) Vệ tinh — Sentinel-2 (10m resolution, 5 ngày/lần) mô hình hóa năng suất bằng Random Forest (R²=0,84); (4) AI bệnh cây — ResNet-50 fine-tune trên 15.000 ảnh lá lúa phân loại 8 bệnh phổ biến, accuracy 91,3%. Kết quả 2 vụ: nhóm ứng dụng công nghệ (n=60 hộ) vs nhóm đối chứng (n=60 hộ truyền thống): giảm tưới 29,7% (tiết kiệm 2,4 triệu VNĐ/ha/vụ), giảm phân đạm 24,8%, giảm thuốc BVTV 31,2%, năng suất tăng 11,8% (từ 6,1 lên 6,8 tấn/ha). ROI: dương từ vụ thứ 2.','2026-04-26 08:01:08'),
 
-- paper 68: Mangrove Mekong Delta
(78,68,'short','Rừng ngập mặn Cà Mau đã mất 50.000 ha (1980-2020), tương đương 2.500 ha/năm. Dự án phục hồi Kiên Giang (2.100 ha, 2015-2020): tỷ lệ sống sót cây 72%, trữ lượng carbon đạt 85 tấn CO₂/ha sau 5 năm, giá trị hệ sinh thái 12.400 USD/ha/năm. Mô hình cộng đồng (rừng - tôm bền vững) cho kết quả phục hồi bền vững hơn mô hình chỉ trồng rừng thuần túy.','2026-05-03 09:31:13'),
 
-- paper 70: Urban Heat Island Vietnam
(79,70,'short','Nhiệt độ bề mặt đất (LST) tại nội thành Hà Nội cao hơn ngoại ô 4,2-6,8°C vào mùa hè (Landsat 8, 2016-2024). Khu Hoàn Kiếm, Đống Đa và Hai Bà Trưng là điểm nóng nhất. Mái nhà xanh thí điểm tại 12 tòa nhà ở Hà Nội giảm LST cục bộ 3-5°C và tiêu thụ điện điều hòa 18%. Trồng thêm 40.000 cây đường phố có thể giảm nhiệt độ không khí trung bình Hà Nội 0,8°C theo mô hình WRF.','2026-05-09 10:00:59'),
 
-- paper 71: Battery Technology EV
(80,71,'short','LFP (Lithium Iron Phosphate) đang chiếm lĩnh phân khúc xe điện giá phổ thông: chi phí 80-100 USD/kWh, an toàn nhiệt tốt hơn NMC, tuổi thọ 3.000-4.000 chu kỳ nhưng mật độ năng lượng thấp hơn. NMC811 cho sedan cao cấp: 250-300 Wh/kg, 1.000-2.000 chu kỳ. Pin thể rắn Toyota dự kiến thương mại hóa 2027-2028: 400 Wh/kg, sạc 10-80% trong 10 phút.','2026-04-14 10:01:27'),
(81,71,'detailed','Phân tích toàn diện công nghệ pin xe điện năm 2024. Lithium-ion thương mại hiện tại: (1) NMC 811 (Ni80-Mn10-Co10): năng lượng riêng 250-300 Wh/kg, 1.000-2.000 chu kỳ đến 80% SOH, chi phí ~110 USD/kWh — dùng cho Tesla Model S/X, Porsche Taycan; (2) LFP (LiFePO₄): 150-200 Wh/kg, 3.000-4.000 chu kỳ, chi phí 80-100 USD/kWh, không có Co/Ni, ổn định nhiệt tốt — Tesla Model 3 SR, BYD Blade Battery, VinFast VF 3/5; (3) NCA (Ni80-Co15-Al5): 270-310 Wh/kg, Tesla Model 3/Y — đang chuyển dần sang NMC. Thế hệ kế tiếp — Pin thể rắn (2027-2030): (1) Anode silicon (thay graphite): mật độ 10x cao hơn graphite nhưng giãn nở 300% khi sạc — giải quyết bằng nano-silicon composite; (2) Solid electrolyte (oxide/sulfide/polymer): loại bỏ điện phân lỏng dễ cháy, cho phép anode lithium kim loại (3.860 mAh/g vs graphite 372 mAh/g). Mục tiêu: 400-500 Wh/kg, sạc 10 phút, >5.000 chu kỳ, chi phí <60 USD/kWh. Players: Toyota (oxyd-sulfide), QuantumScape (oxide/Li metal, backed by VW), Solid Power (Samsung SDI). Điểm cổ chai: sản xuất điện cực thể rắn quy mô lớn.','2026-04-14 10:01:27'),
 
-- paper 73: Supply Chain Resilience
(82,73,'short','Khảo sát 400 doanh nghiệp ASEAN hậu COVID: 71% bị gián đoạn chuỗi cung ứng nghiêm trọng năm 2021. Các doanh nghiệp phục hồi nhanh nhất có: nhà cung cấp dự phòng từ ≥2 quốc gia, tồn kho an toàn 4-6 tuần nhu cầu và hệ thống visibility chuỗi cung ứng số hóa. Near-shoring (dịch chuyển sản xuất về gần thị trường tiêu thụ) tăng chi phí 8-15% nhưng giảm thời gian giao hàng 40-60%.','2026-04-21 11:01:13'),
 
-- paper 74: Last-mile Delivery
(83,74,'short','VRPTW giải bằng Genetic Algorithm (GA) cho 200 điểm giao hàng: tối ưu hơn tài xế kinh nghiệm 18-23% về quãng đường và 15-20% về thời gian. Crowd-sourced delivery (Lalamove tại TP.HCM) giảm chi phí last-mile 35% so với đội xe riêng nhưng tỷ lệ giao thành công thấp hơn 8%. Robot giao hàng tự hành: chi phí vận hành 1,2 USD/giao hàng vs 4-8 USD với tài xế, phù hợp với mật độ giao hàng cao trong khu đô thị.','2026-05-07 09:01:02'),
 
-- paper 75: AI Regulation
(84,75,'short','EU AI Act là khung pháp lý AI toàn diện nhất thế giới: cấm tuyệt đối social scoring và real-time biometric surveillance; yêu cầu đăng ký và đánh giá conformity cho AI rủi ro cao; phạt đến 35 triệu EUR hoặc 7% doanh thu toàn cầu. Doanh nghiệp AI toàn cầu phải tuân thủ nếu sản phẩm phục vụ người dùng EU — tương tự GDPR. Việt Nam chưa có khung pháp lý AI riêng, đang tham khảo mô hình EU và Singapore.','2026-04-23 10:01:34'),
(85,75,'detailed','So sánh ba khung quản lý AI lớn nhất thế giới theo 12 tiêu chí. EU AI Act (hiệu lực 2025-2026): Phân loại rủi ro 4 tầng — (1) Unacceptable (cấm): social credit, subliminal manipulation, real-time biometric surveillance nơi công cộng trừ ngoại lệ an ninh; (2) High-risk (yêu cầu conformity assessment): AI trong tuyển dụng, tín dụng, tư pháp hình sự, biometric — phải đăng ký EU database và kiểm toán định kỳ; (3) Limited risk: chatbot phải tiết lộ là AI; (4) Minimal risk: AI filter spam — không yêu cầu. Hình phạt: lên đến 35 triệu EUR hoặc 7% doanh thu. Mỹ — Executive Order 14110 (10/2023): yêu cầu báo cáo cho chính phủ với model >10²⁶ FLOPs, safety testing, watermarking AI content, và bảo vệ việc làm Mỹ. NIST AI Risk Management Framework (tự nguyện) được áp dụng rộng. Trung Quốc: Quy định Recommendation Algorithms (2022), Synthetic Content / Deepfake (2022), Generative AI (2023) — tập trung vào kiểm soát nội dung và an ninh quốc gia. So sánh: EU nghiêm ngặt nhất về quyền cá nhân; Mỹ linh hoạt nhất cho đổi mới; Trung Quốc ưu tiên kiểm soát nội dung và ổn định xã hội. Hàm ý cho Việt Nam: cần xây dựng khung pháp lý trước khi AI rủi ro cao được triển khai rộng rãi trong ngành tư pháp và y tế.','2026-04-23 10:01:34'),
 
-- paper 76: IP and Generative AI
(86,76,'short','Vụ kiện NYT vs OpenAI (2023) là thách thức pháp lý lớn nhất cho AI tạo sinh: NYT lập luận GPT-4 có thể tái tạo nội dung báo nguyên văn — vi phạm trực tiếp bản quyền. Câu hỏi pháp lý chưa giải quyết: "fair use" có bao gồm dữ liệu huấn luyện không? Ai là tác giả nội dung AI? Xu hướng: thỏa thuận cấp phép (AP, Reuters đã ký với OpenAI) vs kiện tụng (Getty, Authors Guild).','2026-05-06 15:01:18'),
 
-- paper 77: MBCT Depression
(87,77,'short','MBCT giảm 43% nguy cơ tái phát trầm cảm — hiệu quả tương đương thuốc chống trầm cảm duy trì (OR=0,57 vs 0,59) nhưng không có tác dụng phụ và rẻ hơn 70% chi phí dài hạn. MBCT hoạt động qua cơ chế decentering (quan sát suy nghĩ mà không đồng nhất với chúng), giảm rumination và tăng metacognitive awareness. Khuyến cáo NICE (UK) và APA: MBCT là lựa chọn ưu tiên cho phòng ngừa tái phát trầm cảm tái diễn.','2026-04-29 09:00:56'),
 
-- paper 78: Neuroscience of Learning
(88,78,'short','Spaced repetition (lặp lại cách quãng) là kỹ thuật học hiệu quả nhất theo khoa học thần kinh: học lại sau 1 ngày, 7 ngày, 30 ngày và 90 ngày tối ưu hóa đường cong quên lãng. Retrieval practice (tự kiểm tra) hiệu quả hơn re-reading 50-100% trong kiểm tra sau 1 tuần (effect size d=0,50-1,00). Giấc ngủ 7-9 giờ là điều kiện sinh học thiết yếu — thiếu ngủ giảm khả năng ghi nhớ dài hạn 40%.','2026-05-08 08:31:07'),
 
-- paper 79: Immunotherapy Solid Tumors
(89,79,'short','Pembrolizumab (anti-PD-1) đạt overall response rate 45% ở ung thư phổi không tế bào nhỏ PD-L1 cao (TPS≥50%) với overall survival trung vị 26,3 tháng — gấp đôi hóa trị. Biomarker dự đoán đáp ứng: Tumor Mutational Burden (TMB) ≥10 mut/Mb và MSI-H (mismatch repair deficient). Thách thức: <20% bệnh nhân đạt đáp ứng lâu dài với đơn trị liệu; khối u "lạnh" (ít lymphocyte) cần chiến lược "làm nóng" vi môi trường.','2026-05-01 11:01:37'),
(90,79,'detailed','Immunotherapy cho khối u đặc — cập nhật toàn diện đến ASCO 2024. PD-1/PD-L1 checkpoint inhibitors — cơ chế: tế bào T sau khi nhận diện kháng nguyên khối u tăng PD-1 (marker kiệt sức); tế bào ung thư biểu hiện PD-L1 gắn PD-1 → tắt T cell. Anti-PD-1 (pembrolizumab, nivolumab) cắt đứt liên kết này, tái hoạt hóa T cell. Kết quả lâm sàng: Melanoma — nivolumab + ipilimumab: 5-year OS 52% (so với 8% hóa trị trước đây); NSCLC PD-L1 high — pembrolizumab đơn trị: OS trung vị 26,3 tháng; HNSCC, Bladder, MSI-H (pan-tumor): đáp ứng ổn định. Biomarkers: TMB ≥10 mut/Mb (FDA approved cho pembrolizumab pan-tumor); MSI-H/dMMR (mismatch repair deficient) — response rate 40-42% pan-tumor; PD-L1 TPS — chỉ áp dụng đáng tin cậy cho NSCLC. Thách thức khối u đặc: (1) Fibrotic stroma cản T cell xâm nhập; (2) MDSCs và Tregs ức chế miễn dịch trong vi môi trường; (3) Kháng nguyên ung thư bị downregulate (antigen escape). Chiến lược kết hợp: ICI + anti-VEGF (atezolizumab + bevacizumab cho HCC: OS 19,2 vs 13,4 tháng); ICI + hóa trị; Bispecific antibody (catumaxomab, tebotelimab); CAR-T cho solid tumor (GD2 cho neuroblastoma, EGFRvIII cho glioblastoma — còn nghiên cứu giai đoạn đầu).','2026-05-01 11:01:37'),
 
-- Thêm một số summaries ngắn cho các paper còn lại để bao phủ đầy đủ
(91,52,'detailed','Meta-analysis ESG của Friede, Busch và Bassen (2015, cập nhật 2022) — tổng hợp 1.200 nghiên cứu từ 1970-2022. Phân nhóm theo phương pháp: (1) Portfolio studies — đầu tư ESG cao: 58% outperform, 14% underperform thị trường sau điều chỉnh rủi ro; (2) Corporate finance studies — mối quan hệ ESG-ROA/ROE: 48% tương quan dương, 6% âm; (3) Voting studies — cải thiện governance sau shareholder activism. Phân tích theo yếu tố: G (Governance) là yếu tố dự báo tốt nhất với CFP (Corporate Financial Performance) — board diversity, compensation alignment, anti-takeover provisions; E (Environment) mạnh trong ngành năng lượng và tiêu dùng; S (Social) khó đo lường nhất và tương quan yếu nhất. Phân tích theo giai đoạn: mối tương quan ESG-CFP mạnh hơn trong thị trường gấu (2008, 2020) — ESG hoạt động như "insurance" rủi ro. Phê phán: thiếu chuẩn hóa điểm ESG giữa các rater (Sustainalytics vs MSCI vs Bloomberg tương quan chỉ 0,38-0,65) — "ESG confusion problem." Greenwashing: 23% công ty ESG cao không thực sự giảm carbon footprint tuyệt đối.','2026-04-18 14:01:03'),
 
(92,55,'detailed','Edge AI Survey — phân tích triển khai mô hình ML trên thiết bị biên. Taxonomy thiết bị biên: Class 1 (<1MB RAM): vi điều khiển STM32, Arduino — chỉ chạy mô hình <10KB (keyword spotting, gesture); Class 2 (1-256MB): Raspberry Pi, NVIDIA Nano — CNN nhỏ, object detection light; Class 3 (>256MB): smartphone, gateway AI — full inference. Kỹ thuật nén: (1) Pruning — loại bỏ trọng số nhỏ (unstructured) hoặc toàn bộ filter (structured); structured pruning thân thiện phần cứng hơn, giảm 50-80% FLOP với <2% mất accuracy trên MobileNet; (2) Quantization — INT8 quantization (weight + activation): model size 4x nhỏ hơn, inference 2-3x nhanh hơn, mất accuracy <1% trên ImageNet classification; INT4 aggressive hơn (6-8x nén) với mất 3-5%; (3) Knowledge Distillation (Hinton 2015) — teacher ResNet-50 → student MobileNetV2: student đạt 90% accuracy teacher với 10x ít parameters; (4) Neural Architecture Search (NAS) — tự động tìm kiến trúc tối ưu cho constraint phần cứng (MCUNet cho IoT, EfficientNet). Runtime tốt nhất: TFLite (Google) — hỗ trợ rộng nhất ARM + DSP + NPU; ONNX Runtime — linh hoạt nhất multi-framework; TensorRT (NVIDIA) — tối ưu nhất cho Jetson. Benchmark thực tế: MobileNetV3-Small trên Raspberry Pi 4 (INT8, TFLite): 23ms/inference, accuracy 67,4% ImageNet. EfficientDet-Lite0 object detection: 36ms, mAP 25,9%.','2026-05-01 08:01:12'),
 
(93,60,'detailed','Post-Quantum Cryptography — phân tích kỹ thuật và lộ trình triển khai. Mối đe dọa lượng tử: Thuật toán Shor (1994) phá RSA-2048 trong ~4.000 lỗi logic (tương đương ~1 triệu qubit vật lý với error correction). Dự báo: máy tính lượng tử cryptographically relevant (CRQC) xuất hiện năm 2030-2035 theo CISA. "Harvest now, decrypt later": NSA và APT groups đang thu thập dữ liệu mã hóa hiện tại để giải mã khi CRQC sẵn sàng — dữ liệu y tế, bí mật nhà nước cần bảo mật 20+ năm phải bắt đầu di chuyển ngay. NIST PQC Standards (2024): (1) CRYSTALS-Kyber (ML-KEM) — trao đổi khóa dựa trên Module Learning with Errors (MLWE), khóa công khai 1.184 bytes (vs RSA-2048: 256 bytes), hiệu suất tốt hơn NTRU; (2) CRYSTALS-Dilithium (ML-DSA) — chữ ký số dựa trên MLWE, chữ ký 2.420-4.595 bytes; (3) FALCON — chữ ký nhỏ hơn (897 bytes) nhưng triển khai phức tạp hơn (floating point timing attack risk); (4) SPHINCS+ — hash-based signature, bảo mật cao nhất nhưng chữ ký lớn (8-50KB). Lộ trình di chuyển: 2024-2025 inventory + risk assessment → 2025-2027 hybrid TLS (classical + PQC) → 2027-2030 full PQC migration. Thách thức: legacy embedded systems không thể cập nhật, smart card PKCS#11 API, và overhead size/compute trong IoT.','2026-05-02 10:01:18'),
 
(94,66,'detailed','Epigenetics — cơ chế phân tử và ứng dụng lâm sàng. (1) DNA Methylation: enzyme DNMT3A/B thêm nhóm methyl (-CH₃) vào cytosine trong CpG dinucleotide; CpG islands (>200 bp, CG% >50%) tập trung tại promoter gene — methyl hóa → tắt gene thông qua ngăn transcription factor binding và thu hút MeCP2/MBD proteins thu hẹp chromatin. Demethylation: TET1/2/3 oxy hóa 5mC → 5hmC → loại bỏ bởi base excision repair. (2) Histone modifications: octamer gồm H2A, H2B, H3, H4 (×2) — đuôi N-terminal bị biến đổi: H3K4me3 (promoter hoạt động, KMT2 viết), H3K27me3 (Polycomb im lặng, EZH2 viết, KDM6A xóa), H3K9me3 (heterochromatin), H3K27ac (enhancer hoạt động, HAT viết, HDAC xóa). (3) Chromatin remodeling: SWI/SNF (BAF) complex ATPase trượt nucleosome, mở chromatin cho transcription. ARID1A (thành phần BAF) là gen ức chế khối u thường xuyên bị đột biến nhất (20% ung thư buồng trứng). Bệnh học ung thư: CIMP (CpG Island Methylator Phenotype) im lặng MLH1 → Lynch-like syndrome; promoter methyl hóa BRCA1 trong 10-15% ung thư vú sporadic. Liệu pháp: Azacitidine (DNMT inhibitor) phê duyệt cho MDS/AML; Vorinostat (HDAC inhibitor) cho CTCL; EZH2 inhibitor tazemetostat phê duyệt cho follicular lymphoma ARID1A-mutant.','2026-05-06 13:01:21'),
 
(95,65,'detailed','scRNA-seq — pipeline phân tích tiêu chuẩn và ứng dụng. Nền tảng công nghệ: 10x Genomics Chromium (droplet-based): mỗi GEM chứa 1 tế bào + barcode bead; capture rate ~50-60%; depth 2.000-5.000 genes/tế bào; throughput 500-10.000 tế bào/mẫu; chi phí 1.500-3.000 USD/mẫu. Smart-seq2 (plate-based): full-length transcript, 7.000-10.000 genes, 384 tế bào/run; phù hợp khi cần isoform analysis và rare cell types. SPLIT-seq (combinatorial barcoding): không cần thiết bị microfluidics đặc biệt, tương thích frozen tissue. Pipeline phân tích chuẩn (Seurat v5): (1) QC filtering: loại tế bào chết (mitochondrial reads >20%), doublets (scrublet), và tế bào kém chất lượng (<200 genes); (2) Normalization: sctransform (variance-stabilizing, kiểm soát sequencing depth) thay thế log-normalization; (3) Dimensionality reduction: PCA (top 30 PCs) → UMAP cho visualization; (4) Clustering: Leiden algorithm (resolution 0,5-1,0); (5) Cell type annotation: marker genes + automated tools (SingleR, Azimuth với Human Cell Atlas reference). Advanced: trajectory analysis (Monocle3, scVelo — RNA velocity) cho differentiation; cell-cell communication (CellChat, NicheNet). Ứng dụng đột phá: Human Cell Atlas — >80 triệu tế bào từ 80 cơ quan, phát hiện 500+ loại tế bào mới; Tumor microenvironment mapping: xác định trạng thái T cell exhaustion và M2 macrophage liên quan đến kháng checkpoint inhibitor; COVID-19 lung atlas: cơ chế tổn thương phế nang và bão cytokine.','2026-04-19 09:01:45'),
 
(96,68,'detailed','Rừng ngập mặn Đồng bằng sông Cửu Long — định lượng dịch vụ hệ sinh thái và phân tích phục hồi. Bối cảnh mất rừng: từ 270.000 ha (1943) xuống còn 51.000 ha (2020) — giảm 81%. Nguyên nhân: chuyển đổi sang nuôi tôm thâm canh (65%), đô thị hóa ven biển (20%), khai thác gỗ (10%), xói lở do thiếu phù sa từ đập thủy điện Mekong (5%). Định lượng 5 dịch vụ hệ sinh thái: (1) Cô lập carbon — đo bằng core sampling (100-150cm sâu): 8-12 tấn CO₂/ha/năm (gấp 3-5× rừng nhiệt đới trên cạn do tốc độ tích lũy carbon trong đất yếm khí); tổng trữ lượng 2.200 tấn CO₂/ha (trên mặt đất + dưới đất); giá trị theo carbon credits: 2.000-4.000 USD/ha. (2) Bảo vệ bờ biển — mô phỏng SWAN: dải rừng 500m giảm 70-80% năng lượng sóng, giảm xói lở 90%; giá trị bảo vệ công trình bờ biển: 3.500-8.000 USD/ha/năm. (3) Thủy sản — tôm, cua, cá sử dụng rừng ngập mặn là nursery habitat: năng suất thủy sản giảm 1,5-2 kg/ha/năm khi mất 1% rừng. (4) Lọc nước — hấp thu nitơ và phospho từ nước thải nông nghiệp: 400-600 kg N/ha/năm. (5) Du lịch sinh thái: 800-1.200 USD/ha/năm tại các khu bảo tồn. Tổng giá trị: 12.400-18.000 USD/ha/năm — cao gấp 5-8× thu nhập nuôi tôm thâm canh 1.500-2.500 USD/ha/năm. Phân tích 15 dự án phục hồi (2015-2023): tỷ lệ sống cây 45-87% (trung bình 65%). Yếu tố thành công: lựa chọn đúng loài theo độ mặn và tần suất ngập; cộng đồng tham gia; và mô hình tôm-rừng (silvofishery) 30-70% tán che.','2026-05-03 09:31:13');
